insert into public.recipes (id, name, description, meal_type, main, emoji, prep_time_min, difficulty, calories, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, ingredients, seasonings, instructions, appliances, keywords, dietary_tags, sort) values
  ('b-banana-peanut-butter-oatmeal', 'Banana Peanut Butter Oatmeal', 'Creamy stovetop oats with sliced banana and a spoon of peanut butter', 'breakfast', 'oats', '🥣', 10, 'quick', 553, 21, 84, 17, 10, 30, 190, '[{"name":"oats","amount":60,"unit":"g"},{"name":"milk","amount":250,"unit":"ml"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"peanut butter","amount":15,"unit":"g"}]'::jsonb, '["pinch of salt","pinch of cinnamon"]'::jsonb, '["Put the oats, milk and a pinch of salt in a small pot over medium heat","Simmer for 4 to 5 minutes, stirring often, until thick and creamy","Slice the banana and stir half of it into the oats","Pour into a bowl and top with the rest of the banana, the peanut butter and a little cinnamon"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","oats","milk","banana","peanut butter","stovetop","breakfast"]'::jsonb, '["vegetarian","halal","kosher"]'::jsonb, 0),
  ('b-apple-cinnamon-oatmeal', 'Apple Cinnamon Oatmeal', 'Warm oats cooked with diced apple, cinnamon and a drizzle of honey', 'breakfast', 'oats', '🍎', 12, 'quick', 480, 17, 86, 9, 10, 41, 127, '[{"name":"oats","amount":60,"unit":"g"},{"name":"milk","amount":250,"unit":"ml"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp cinnamon","pinch of salt"]'::jsonb, '["Core the apple and cut it into small cubes","Put the oats, milk, cinnamon, salt and two thirds of the apple in a small pot","Simmer over medium heat for 5 to 6 minutes, stirring often, until the oats are soft","Serve topped with the remaining apple and the honey"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","oats","milk","apple","honey","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 1),
  ('b-coconut-berry-overnight-oats', 'Coconut Berry Overnight Oats', 'No-cook oats soaked overnight in coconut milk, topped with berries', 'breakfast', 'oats', '🫐', 5, 'quick', 456, 11, 61, 21, 10, 13, 16, '[{"name":"oats","amount":60,"unit":"g"},{"name":"coconut milk","amount":80,"unit":"g"},{"name":"blueberries","amount":80,"unit":"g"},{"name":"strawberries","amount":80,"unit":"g"}]'::jsonb, '["{120} ml water","pinch of salt"]'::jsonb, '["Stir the oats, coconut milk, water and salt together in a jar or bowl","Cover and leave in the fridge overnight, or for at least 4 hours","In the morning stir well and loosen with a splash of water if it is too thick","Slice the strawberries and serve the oats topped with both berries"]'::jsonb, '[]'::jsonb, '["fresh","quick","oats","coconut milk","blueberries","strawberries","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 2),
  ('b-peanut-butter-banana-toast', 'Peanut Butter Banana Toast', 'Toasted wholemeal bread with peanut butter and banana slices', 'breakfast', 'bread', '🍌', 5, 'quick', 463, 17, 64, 18, 9, 21, 448, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"peanut butter","amount":30,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Toast the bread until golden","Spread the peanut butter over both slices","Slice the banana, lay it on top and dust with cinnamon"]'::jsonb, '[]'::jsonb, '["quick","bread","peanut butter","banana","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","halal","kosher"]'::jsonb, 3),
  ('b-avocado-tomato-toast', 'Avocado Tomato Toast', 'Smashed avocado on toast with fresh tomato, lemon and olive oil', 'breakfast', 'avocado', '🥑', 8, 'quick', 463, 12, 46, 28, 15, 7, 333, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":100,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice","pinch of chili flakes"]'::jsonb, '["Toast the bread","Halve the avocado, scoop the flesh into a bowl and mash it with a fork, salt, pepper and a squeeze of lemon","Slice the tomato","Spread the avocado on the toast, top with tomato, drizzle with the olive oil and finish with chili flakes"]'::jsonb, '[]'::jsonb, '["spicy","fresh","quick","bread","avocado","tomato","olive oil","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 4),
  ('b-avocado-egg-toast', 'Avocado Toast with Fried Eggs', 'Wholemeal toast with smashed avocado and two fried eggs', 'breakfast', 'eggs', '🍳', 10, 'quick', 602, 25, 43, 38, 14, 4, 485, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper","pinch of chili flakes"]'::jsonb, '["Toast the bread","Mash the avocado with salt and pepper and spread it over the toast","Heat the oil in a pan over medium heat and fry the eggs for 2 to 3 minutes until the whites are set","Slide an egg onto each slice and season with pepper and chili flakes"]'::jsonb, '["stovetop"]'::jsonb, '["spicy","quick","hearty","bread","avocado","eggs","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 5),
  ('b-greek-yogurt-berry-bowl', 'Greek Yogurt Berry Bowl', 'Thick Greek yogurt with blueberries, strawberries and honey', 'breakfast', 'greek yogurt', '🍓', 5, 'quick', 355, 24, 39, 13, 3, 33, 90, '[{"name":"greek yogurt","amount":250,"unit":"g"},{"name":"blueberries","amount":75,"unit":"g"},{"name":"strawberries","amount":75,"unit":"g"},{"name":"honey","amount":15,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Spoon the yogurt into a bowl","Halve or slice the strawberries","Top the yogurt with the berries and drizzle with the honey"]'::jsonb, '[]'::jsonb, '["fresh","quick","light","greek yogurt","blueberries","strawberries","honey","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 6),
  ('b-apple-bircher-muesli', 'Apple Bircher Muesli', 'Oats soaked in yogurt with grated apple and honey', 'breakfast', 'yogurt', '🥣', 10, 'quick', 398, 13, 70, 9, 8, 37, 97, '[{"name":"yogurt","amount":200,"unit":"g"},{"name":"oats","amount":40,"unit":"g"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Coarsely grate the apple, leaving the core behind","Stir the oats, yogurt, grated apple and cinnamon together in a bowl","Leave for at least 10 minutes, or overnight in the fridge, so the oats soften","Drizzle with the honey before serving"]'::jsonb, '[]'::jsonb, '["fresh","quick","light","yogurt","oats","apple","honey","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 7),
  ('b-spinach-feta-scrambled-eggs', 'Spinach and Feta Scrambled Eggs', 'Soft scrambled eggs with wilted spinach, feta and fresh tomato', 'breakfast', 'eggs', '🍳', 10, 'quick', 414, 30, 10, 29, 3, 4, 790, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"spinach","amount":80,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Beat the eggs with a little pepper; the feta is salty, so add no salt","Melt the butter in a pan over medium heat and wilt the spinach for about 1 minute","Pour in the eggs and stir gently for 2 to 3 minutes until just set","Crumble in the feta, fold once and serve with the sliced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","eggs","spinach","feta","tomato","butter","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 8),
  ('b-veggie-omelette', 'Pepper and Mushroom Omelette', 'A folded three-egg omelette filled with peppers, mushrooms and onion', 'breakfast', 'eggs', '🍳', 12, 'quick', 321, 24, 10, 21, 2, 6, 241, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"peppers","amount":60,"unit":"g"},{"name":"mushrooms","amount":60,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Dice the pepper and onion and slice the mushrooms","Heat the oil in a non-stick pan and cook the vegetables for 4 to 5 minutes until soft, then tip them onto a plate","Beat the eggs with salt and pepper, pour into the pan and cook over medium heat until almost set","Spoon the vegetables over one half, fold the omelette over and cook 1 more minute"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","eggs","peppers","mushrooms","onion","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 9),
  ('b-ham-cheese-omelette', 'Ham and Cheese Omelette with Toast', 'A quick omelette with ham and melted cheese, served with buttered toast', 'breakfast', 'eggs', '🧀', 10, 'quick', 454, 32, 18, 27, 3, 3, 919, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"ham","amount":40,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Beat the eggs with pepper, cut the ham into strips and grate the cheese","Melt half the butter in a non-stick pan over medium heat and pour in the eggs","When the eggs are almost set, scatter the ham and cheese over one half and fold the omelette over","Cook 1 more minute until the cheese melts and serve with the toasted, buttered bread"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","eggs","ham","cheese","bread","butter","stovetop","breakfast"]'::jsonb, '["nut-allergy"]'::jsonb, 10),
  ('b-bacon-eggs-toast', 'Bacon and Eggs with Toast', 'Crispy bacon, fried eggs and pan-warmed tomato with toast', 'breakfast', 'eggs', '🥓', 15, 'quick', 548, 30, 35, 32, 5, 6, 855, '[{"name":"bacon","amount":50,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"tomato","amount":100,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Lay the bacon in a cold pan and cook over medium heat for 5 to 6 minutes, turning once, until crisp, then move it to a plate","Halve the tomato and fry it cut side down in the bacon fat for 2 minutes","Fry the eggs in the same pan for 2 to 3 minutes until the whites are set","Toast the bread and serve everything together with a little pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","bacon","eggs","bread","tomato","stovetop","breakfast"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, 11),
  ('b-tofu-scramble-toast', 'Tofu Scramble on Toast', 'Golden scrambled tofu with spinach and peppers on wholemeal toast', 'breakfast', 'tofu', '🧈', 15, 'quick', 478, 37, 43, 21, 11, 7, 391, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"spinach","amount":60,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"oil","amount":5,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"}]'::jsonb, '["1/2 tsp turmeric","salt","black pepper"]'::jsonb, '["Finely dice the onion and pepper and cook them in the oil over medium heat for 3 minutes","Crumble the tofu into the pan with your hands and add the turmeric, salt and pepper","Cook for 4 to 5 minutes, stirring, until the tofu is hot and lightly golden","Stir in the spinach until it wilts and pile the scramble onto the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["quick","tofu","spinach","peppers","onion","oil","bread","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 12),
  ('b-chickpea-potato-hash', 'Chickpea and Potato Breakfast Hash', 'Crispy pan-fried potatoes with chickpeas, onion and spinach', 'breakfast', 'chickpeas', '🥔', 25, 'balanced', 441, 14, 68, 14, 14, 9, 349, '[{"name":"potatoes","amount":200,"unit":"g"},{"name":"chickpeas","amount":120,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp smoked paprika","salt","black pepper"]'::jsonb, '["Cut the potatoes into 1 cm cubes and dice the onion","Heat the oil in a wide pan and fry the potatoes over medium heat for 12 to 15 minutes, turning now and then, until golden and tender","Add the onion, drained chickpeas, paprika, salt and pepper and cook 4 more minutes","Stir in the spinach until it wilts and serve hot"]'::jsonb, '["stovetop"]'::jsonb, '["potatoes","chickpeas","onion","spinach","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 13),
  ('b-shakshuka', 'Shakshuka', 'Eggs poached in a spiced tomato and pepper sauce', 'breakfast', 'eggs', '🍅', 25, 'balanced', 342, 18, 23, 21, 8, 13, 451, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"chopped tomatoes","amount":250,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","pinch of chili flakes","salt","black pepper"]'::jsonb, '["Slice the onion and pepper and finely chop the garlic","Heat the olive oil in a small pan and soften the onion and pepper for 5 minutes, then add the garlic and spices for 1 minute","Pour in the chopped tomatoes, season and simmer for 8 to 10 minutes until slightly thickened","Make {n:eggs} wells in the sauce, crack in the eggs, cover and cook 4 to 5 minutes until the whites are set"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","comfort","light","eggs","chopped tomatoes","peppers","onion","garlic","olive oil","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 14),
  ('b-cottage-cheese-apple-bowl', 'Cottage Cheese Bowl with Apple and Honey', 'High-protein cottage cheese with crisp apple, honey and cinnamon', 'breakfast', 'cottage cheese', '🍏', 5, 'quick', 320, 23, 40, 9, 4, 32, 632, '[{"name":"cottage cheese","amount":200,"unit":"g"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Spoon the cottage cheese into a bowl","Core the apple and cut it into thin slices or small cubes","Top the cottage cheese with the apple, drizzle with honey and dust with cinnamon"]'::jsonb, '[]'::jsonb, '["fresh","quick","light","cottage cheese","apple","honey","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 15),
  ('b-pancakes-strawberries', 'Pancakes with Strawberries', 'Thin homemade pancakes with fresh strawberries and honey', 'breakfast', 'flour', '🥞', 25, 'balanced', 508, 18, 72, 17, 4, 24, 203, '[{"name":"flour","amount":60,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"milk","amount":120,"unit":"ml"},{"name":"butter","amount":10,"unit":"g"},{"name":"strawberries","amount":100,"unit":"g"},{"name":"honey","amount":15,"unit":"g"}]'::jsonb, '["pinch of salt"]'::jsonb, '["Whisk the flour, egg, milk and salt into a smooth batter and let it rest for 5 minutes","Melt a little of the butter in a non-stick pan over medium heat","Pour in a thin layer of batter, cook about 1 minute per side until golden, and repeat with the rest of the batter","Slice the strawberries and serve the pancakes topped with them and the honey"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","flour","eggs","milk","butter","strawberries","honey","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 16),
  ('b-banana-egg-pancakes', 'Banana Egg Pancakes', 'Flourless two-ingredient pancakes with blueberries', 'breakfast', 'eggs', '🥞', 12, 'quick', 343, 16, 37, 16, 5, 21, 158, '[{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"blueberries","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Mash the banana very smooth in a bowl, then whisk in the eggs and cinnamon","Heat the oil in a non-stick pan over medium-low heat","Drop in small spoonfuls of batter and cook about 2 minutes per side, turning carefully","Serve topped with the blueberries"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","banana","eggs","blueberries","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 17),
  ('b-breakfast-burrito', 'Breakfast Burrito', 'A warm tortilla filled with scrambled eggs, beans, cheese and tomato', 'breakfast', 'eggs', '🌯', 12, 'quick', 559, 30, 46, 28, 6, 7, 944, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"cheese","amount":25,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of ground cumin","salt","black pepper"]'::jsonb, '["Dice the tomato, grate the cheese and drain the beans","Heat the oil in a pan, warm the beans with the cumin for 1 minute, then pour in the beaten eggs and scramble until just set","Warm the tortilla in a dry pan for 20 seconds per side","Fill it with the eggs and beans, cheese and tomato, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","hearty","tortilla","eggs","kidney beans","cheese","tomato","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 18),
  ('b-sweet-potato-bean-hash', 'Sweet Potato and Bean Hash', 'Pan-fried sweet potato with kidney beans, peppers and onion', 'breakfast', 'sweet potato', '🍠', 25, 'balanced', 420, 12, 70, 12, 14, 17, 346, '[{"name":"sweet potato","amount":200,"unit":"g"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","1/2 tsp smoked paprika","salt","black pepper"]'::jsonb, '["Peel the sweet potato and cut it into 1 cm cubes; dice the onion and pepper","Heat the olive oil in a wide pan and fry the sweet potato over medium heat for 10 to 12 minutes until tender and browned","Add the onion, pepper and spices and cook 4 more minutes","Stir in the drained beans, heat through for 2 minutes and season to taste"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","sweet potato","kidney beans","peppers","onion","olive oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 19),
  ('b-spicy-egg-avocado-taco', 'Spicy Egg and Avocado Breakfast Taco', 'Tortilla with chili scrambled eggs, avocado and tomato', 'breakfast', 'eggs', '🌮', 10, 'quick', 620, 22, 45, 41, 12, 5, 611, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","salt","squeeze of lime juice"]'::jsonb, '["Beat the eggs with the chili flakes and salt and scramble them in the oil over medium heat for 2 minutes","Mash the avocado with lime juice and a pinch of salt","Warm the tortilla in a dry pan, spread with the avocado and top with the eggs and diced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","hearty","tortilla","eggs","avocado","tomato","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 20),
  ('b-chili-scrambled-eggs-toast', 'Chili Scrambled Eggs on Toast', 'Soft scrambled eggs with chili and tomato on buttered toast', 'breakfast', 'eggs', '🌶️', 8, 'quick', 463, 30, 34, 22, 5, 6, 589, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"butter","amount":5,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","salt"]'::jsonb, '["Beat the eggs with the chili flakes and salt","Melt the butter in a pan over medium-low heat, add the diced tomato for 1 minute, then pour in the eggs","Stir gently for 2 to 3 minutes until softly set","Pile onto the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["spicy","quick","eggs","bread","butter","tomato","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 21),
  ('b-spicy-tofu-bean-wrap', 'Spicy Tofu and Bean Breakfast Wrap', 'Tortilla with chili tofu scramble, kidney beans and peppers', 'breakfast', 'tofu', '🌯', 12, 'quick', 488, 31, 49, 21, 9, 7, 599, '[{"name":"tofu","amount":120,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"peppers","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp ground cumin","1/2 tsp turmeric","salt"]'::jsonb, '["Dice the peppers and cook them in the oil for 2 minutes","Crumble in the tofu with the chili flakes, cumin, turmeric and salt and cook for 4 minutes","Add the drained kidney beans and heat through","Warm the tortilla, add the filling and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","tofu","tortilla","kidney beans","peppers","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 22),
  ('b-harissa-chickpeas-toast', 'Harissa Chickpeas on Toast', 'Warm spiced chickpeas with tomato and spinach on toast', 'breakfast', 'chickpeas', '🌶️', 10, 'quick', 441, 19, 62, 14, 14, 11, 650, '[{"name":"chickpeas","amount":120,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"tomato","amount":100,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp harissa paste","salt","squeeze of lemon juice"]'::jsonb, '["Warm the olive oil in a pan and cook the diced tomato with the harissa for 2 minutes","Add the drained chickpeas and cook for 3 minutes, lightly crushing some of them","Stir in the spinach until wilted and season with salt and lemon juice","Spoon over the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","chickpeas","bread","tomato","spinach","olive oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 23),
  ('b-menemen', 'Menemen', 'Turkish eggs scrambled into soft tomatoes and peppers, with bread', 'breakfast', 'eggs', '🍅', 15, 'quick', 481, 28, 31, 28, 7, 12, 408, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"tomato","amount":200,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp paprika","salt"]'::jsonb, '["Dice the onion and peppers and soften them in the olive oil for 4 minutes","Add the chopped tomato, chili flakes, paprika and salt and cook for 5 minutes until saucy","Pour in the lightly beaten eggs and stir gently for 2 minutes until just set","Serve from the pan with the bread"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","eggs","tomato","peppers","onion","olive oil","bread","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 24),
  ('b-yogurt-banana-oat-bowl', 'Yogurt, Banana and Oat Bowl', 'Plain yogurt with banana, strawberries and a handful of oats', 'breakfast', 'yogurt', '🍌', 5, 'quick', 368, 13, 63, 9, 8, 28, 96, '[{"name":"yogurt","amount":200,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"oats","amount":30,"unit":"g"},{"name":"strawberries","amount":80,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Spoon the yogurt into a bowl and stir in the oats","Slice the banana and strawberries","Top the yogurt with the fruit and a pinch of cinnamon"]'::jsonb, '[]'::jsonb, '["fresh","quick","light","yogurt","banana","oats","strawberries","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 25),
  ('b-cottage-cheese-tomato-toast', 'Cottage Cheese and Tomato Toast', 'Toast piled with cottage cheese, tomato and cucumber', 'breakfast', 'cottage cheese', '🍅', 5, 'quick', 350, 27, 41, 9, 6, 11, 797, '[{"name":"cottage cheese","amount":150,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"}]'::jsonb, '["black pepper","pinch of salt","pinch of dried oregano"]'::jsonb, '["Toast the bread","Spread the cottage cheese over both slices","Top with the sliced tomato and cucumber and season with salt, pepper and oregano"]'::jsonb, '[]'::jsonb, '["fresh","quick","light","cottage cheese","bread","tomato","cucumber","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 26),
  ('b-fruit-salad-yogurt', 'Fruit Salad with Yogurt', 'Apple, banana and berries with plain yogurt', 'breakfast', 'yogurt', '🍓', 8, 'quick', 358, 8, 76, 6, 11, 51, 74, '[{"name":"yogurt","amount":150,"unit":"g"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"strawberries","amount":100,"unit":"g"},{"name":"blueberries","amount":60,"unit":"g"}]'::jsonb, '["squeeze of lemon juice"]'::jsonb, '["Core and dice the apple and slice the banana and strawberries","Toss all the fruit, including the blueberries, with a squeeze of lemon juice","Serve with the yogurt spooned over"]'::jsonb, '[]'::jsonb, '["fresh","quick","light","yogurt","apple","banana","strawberries","blueberries","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 27),
  ('b-banana-berry-porridge', 'Dairy-Free Banana Berry Porridge', 'Oats cooked in water with mashed banana, blueberries and peanut butter', 'breakfast', 'oats', '🥣', 10, 'quick', 428, 12, 79, 10, 11, 22, 48, '[{"name":"oats","amount":60,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"blueberries","amount":60,"unit":"g"},{"name":"peanut butter","amount":10,"unit":"g"}]'::jsonb, '["{300} ml water","pinch of salt","pinch of cinnamon"]'::jsonb, '["Mash half the banana and put it in a pot with the oats, water and salt","Simmer for 5 minutes, stirring, until thick and creamy","Stir in half the blueberries","Serve topped with the remaining banana, sliced, the rest of the blueberries, the peanut butter and cinnamon"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","oats","banana","blueberries","peanut butter","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","halal","kosher"]'::jsonb, 28),
  ('b-strawberry-banana-smoothie-bowl', 'Strawberry Banana Smoothie Bowl', 'Thick blended yogurt and fruit bowl topped with oats and honey', 'breakfast', 'greek yogurt', '🍓', 8, 'quick', 464, 23, 70, 12, 8, 37, 74, '[{"name":"greek yogurt","amount":200,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"strawberries","amount":120,"unit":"g"},{"name":"oats","amount":25,"unit":"g"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Blend the yogurt with half the banana and two thirds of the strawberries until smooth and thick","Pour into a bowl","Top with the remaining banana and strawberries, sliced, the oats and the honey"]'::jsonb, '[]'::jsonb, '["fresh","quick","greek yogurt","banana","strawberries","oats","honey","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 29),
  ('b-french-toast', 'French Toast with Strawberries', 'Egg-soaked bread fried in butter, with strawberries and honey', 'breakfast', 'eggs', '🍞', 15, 'quick', 591, 30, 64, 24, 8, 21, 738, '[{"name":"bread","amount":105,"unit":"g","label":"3 slices"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"milk","amount":80,"unit":"ml"},{"name":"butter","amount":10,"unit":"g"},{"name":"strawberries","amount":80,"unit":"g"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp cinnamon","pinch of salt"]'::jsonb, '["Beat the eggs with the milk, cinnamon and salt in a shallow dish","Soak each slice of bread in the mixture for 20 seconds per side","Fry in the butter over medium heat for 2 to 3 minutes per side until golden","Serve topped with the sliced strawberries and the honey"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","bread","eggs","milk","butter","strawberries","honey","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 30),
  ('b-full-cooked-breakfast', 'Full Cooked Breakfast', 'Bacon, fried eggs, mushrooms and tomato with buttered toast', 'breakfast', 'eggs', '🍳', 20, 'quick', 602, 33, 37, 36, 6, 8, 891, '[{"name":"bacon","amount":50,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"mushrooms","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Cook the bacon in a dry pan over medium heat for 5 to 6 minutes until crisp and move it to a plate","Fry the halved mushrooms and the halved tomato in the bacon fat for 4 minutes","Push them aside and fry the eggs for 2 to 3 minutes until the whites are set","Serve everything with the toasted, buttered bread and a little pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","bacon","eggs","mushrooms","tomato","bread","butter","stovetop","breakfast"]'::jsonb, '["nut-allergy"]'::jsonb, 31),
  ('b-egg-ham-cheese-toastie', 'Egg, Ham and Cheese Toastie', 'Pan-toasted sandwich with a fried egg, ham and melted cheese', 'breakfast', 'eggs', '🥪', 10, 'quick', 463, 30, 32, 23, 5, 4, 1000, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"ham","amount":40,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Fry the egg in half the butter for 2 minutes, flip it and cook 30 seconds more","Layer the ham, egg and sliced cheese between the bread","Toast the sandwich in the remaining butter over medium heat for 2 minutes per side until golden and the cheese melts"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","bread","eggs","ham","cheese","butter","stovetop","breakfast"]'::jsonb, '["nut-allergy"]'::jsonb, 32),
  ('b-salmon-scrambled-eggs-toast', 'Scrambled Eggs with Salmon on Toast', 'Soft scrambled eggs folded with flaked salmon on buttered toast', 'breakfast', 'eggs', '🐟', 12, 'quick', 515, 37, 31, 26, 4, 3, 548, '[{"name":"salmon","amount":70,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper","squeeze of lemon juice"]'::jsonb, '["Fry the salmon in a non-stick pan over medium heat for 3 minutes per side, then break it into flakes","Melt the butter in the pan, pour in the beaten eggs and stir gently for 2 minutes until softly set","Fold in the salmon","Serve on the toasted bread with pepper and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["quick","hearty","salmon","eggs","bread","butter","stovetop","breakfast"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, 33),
  ('b-banana-oat-pancakes', 'Banana Oat Pancakes', 'Blender pancakes made from oats, banana and egg, with blueberries', 'breakfast', 'oats', '🥞', 15, 'quick', 484, 17, 73, 15, 10, 25, 112, '[{"name":"oats","amount":50,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"milk","amount":60,"unit":"ml"},{"name":"oil","amount":5,"unit":"g"},{"name":"blueberries","amount":60,"unit":"g"}]'::jsonb, '["pinch of cinnamon","pinch of salt"]'::jsonb, '["Blend the oats, banana, egg, milk, cinnamon and salt into a smooth batter and let it stand for 2 minutes","Heat the oil in a non-stick pan over medium heat","Cook small pancakes for about 2 minutes per side until golden","Serve topped with the blueberries"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","oats","banana","eggs","milk","oil","blueberries","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 34),
  ('b-cheese-tomato-omelette', 'Cheese and Tomato Omelette', 'Three-egg omelette with melted cheese and fresh tomato', 'breakfast', 'eggs', '🧀', 8, 'quick', 397, 29, 6, 28, 1, 4, 517, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"cheese","amount":30,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Beat the eggs with salt and pepper and dice the tomato","Melt the butter in a non-stick pan over medium heat and pour in the eggs","When almost set, scatter the grated cheese and tomato over one half","Fold over and cook 1 more minute"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","eggs","cheese","tomato","butter","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 35),
  ('b-avocado-chickpea-smash-toast', 'Avocado and Chickpea Smash on Toast', 'Toast topped with avocado and chickpeas mashed with lemon', 'breakfast', 'chickpeas', '🥑', 8, 'quick', 529, 18, 65, 25, 20, 9, 526, '[{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"chickpeas","amount":80,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","pinch of paprika"]'::jsonb, '["Toast the bread","Mash the avocado and drained chickpeas roughly with the juice of the lemon, salt and pepper","Pile onto the toast and dust with paprika"]'::jsonb, '[]'::jsonb, '["fresh","quick","avocado","chickpeas","bread","lemon","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 36),
  ('b-tofu-vegetable-scramble', 'Tofu and Vegetable Scramble', 'Scrambled tofu with mushrooms, spinach and tomato', 'breakfast', 'tofu', '🍄', 12, 'quick', 310, 31, 13, 19, 7, 4, 77, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"mushrooms","amount":80,"unit":"g"},{"name":"spinach","amount":60,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp turmeric","salt","black pepper"]'::jsonb, '["Slice the mushrooms and fry them in the oil for 3 minutes","Crumble in the tofu with the turmeric, salt and pepper and cook for 4 minutes","Add the diced tomato and spinach and cook until the spinach wilts"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","tofu","mushrooms","spinach","tomato","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 37),
  ('b-rice-porridge-cinnamon-apple', 'Creamy Rice Porridge with Cinnamon Apple', 'Rice simmered in milk until creamy, topped with apple and honey', 'breakfast', 'rice', '🍚', 35, 'balanced', 461, 14, 88, 7, 5, 43, 150, '[{"name":"rice","amount":50,"unit":"g"},{"name":"milk","amount":300,"unit":"ml"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp cinnamon","pinch of salt"]'::jsonb, '["Put the rice, milk and salt in a pot and bring to a gentle simmer","Cook on low heat for 25 to 30 minutes, stirring often, until the rice is soft and the porridge is creamy","Dice the apple and stir half of it in for the last 5 minutes","Serve topped with the remaining apple, the honey and the cinnamon"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","rice","milk","apple","honey","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 38),
  ('b-feta-tomato-egg-toast', 'Feta, Tomato and Egg Toast', 'Toast with crumbled feta, tomato, olive oil and a fried egg', 'breakfast', 'eggs', '🍅', 8, 'quick', 453, 24, 37, 24, 6, 6, 972, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"feta","amount":50,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of dried oregano","black pepper"]'::jsonb, '["Toast the bread and top it with the sliced tomato and crumbled feta","Fry the egg in the olive oil for 2 to 3 minutes","Put the egg on top and finish with oregano and pepper"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","bread","feta","tomato","eggs","olive oil","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 39),
  ('b-big-breakfast-burrito', 'Big Breakfast Burrito', 'Two tortillas filled with scrambled eggs, beans, cheese and tomato', 'breakfast', 'eggs', '🌯', 12, 'quick', 761, 37, 76, 34, 8, 9, 1427, '[{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","salt","black pepper"]'::jsonb, '["Warm the drained kidney beans with the cumin in the oil for 1 minute","Pour in the beaten eggs, season and scramble until just set","Warm the tortillas in a dry pan","Divide the eggs and beans, grated cheese and diced tomato between them, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","hearty","tortilla","eggs","kidney beans","cheese","tomato","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 40),
  ('b-protein-oats', 'Peanut Butter Protein Oats', 'Thick oats with Greek yogurt, peanut butter and banana', 'breakfast', 'oats', '🥣', 10, 'quick', 785, 35, 103, 29, 12, 35, 269, '[{"name":"oats","amount":80,"unit":"g"},{"name":"milk","amount":250,"unit":"ml"},{"name":"greek yogurt","amount":100,"unit":"g"},{"name":"peanut butter","amount":25,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"}]'::jsonb, '["pinch of salt","pinch of cinnamon"]'::jsonb, '["Simmer the oats with the milk and salt for 4 to 5 minutes, stirring, until thick","Take off the heat and stir in half the yogurt","Top with the rest of the yogurt, the sliced banana, the peanut butter and cinnamon"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","oats","milk","greek yogurt","peanut butter","banana","stovetop","breakfast"]'::jsonb, '["vegetarian","halal","kosher"]'::jsonb, 41),
  ('b-egg-bacon-cheese-sandwich', 'Egg, Bacon and Cheese Sandwich', 'Triple-decker toasted sandwich with fried eggs, bacon and cheese', 'breakfast', 'eggs', '🥪', 12, 'quick', 722, 40, 46, 41, 6, 6, 1212, '[{"name":"bread","amount":105,"unit":"g","label":"3 slices"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"bacon","amount":40,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Fry the bacon in a dry pan over medium heat for 4 to 5 minutes until crisp and set it aside","Fry the eggs in the bacon fat for 2 minutes, flip and cook 30 seconds more","Toast the bread and butter it","Stack the sandwich with the eggs, bacon and sliced cheese between the slices and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","bread","eggs","bacon","cheese","butter","stovetop","breakfast"]'::jsonb, '["nut-allergy"]'::jsonb, 42),
  ('b-salmon-avocado-egg-toast', 'Salmon, Avocado and Egg Toast', 'Toast with avocado, flaked salmon and fried eggs', 'breakfast', 'eggs', '🥑', 15, 'quick', 724, 42, 43, 44, 14, 4, 532, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"salmon","amount":80,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Fry the salmon in a non-stick pan over medium heat for 3 minutes per side and break it into flakes","Fry the eggs in the same pan for 2 to 3 minutes","Toast the bread and spread it with the avocado mashed with lemon juice and salt","Top with the salmon and eggs and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","hearty","bread","salmon","eggs","avocado","stovetop","breakfast"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 43),
  ('b-loaded-potato-omelette', 'Loaded Potato, Ham and Cheese Omelette', 'Three-egg omelette over fried potatoes with ham and cheese', 'breakfast', 'eggs', '🍳', 20, 'quick', 685, 43, 39, 39, 5, 4, 981, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"cheese","amount":40,"unit":"g"},{"name":"ham","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Cut the potatoes into small cubes and fry them in the oil over medium heat for 10 to 12 minutes until golden and tender","Add the ham cut into strips for 1 minute","Pour over the beaten eggs, seasoned with salt and pepper, and cook gently for 3 minutes until almost set","Scatter with the grated cheese, cover for 1 minute until it melts and fold in half"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","eggs","potatoes","cheese","ham","oil","stovetop","breakfast"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, 44),
  ('b-tofu-scramble-burrito', 'Tofu Scramble Burrito', 'Two tortillas filled with spiced tofu scramble and kidney beans', 'breakfast', 'tofu', '🌯', 15, 'quick', 770, 47, 82, 31, 13, 7, 1093, '[{"name":"tofu","amount":180,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp turmeric","1/2 tsp ground cumin","1/2 tsp smoked paprika","salt"]'::jsonb, '["Crumble the tofu into the hot oil with the turmeric, cumin, paprika and salt and cook for 5 minutes","Add the drained kidney beans and heat through for 2 minutes","Warm the tortillas in a dry pan","Divide the filling between them, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","hearty","tofu","tortilla","kidney beans","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 45),
  ('b-peanut-butter-overnight-oats', 'Peanut Butter Banana Overnight Oats', 'Dairy-free overnight oats with coconut milk, peanut butter and banana', 'breakfast', 'oats', '🥜', 5, 'quick', 746, 21, 97, 34, 14, 19, 142, '[{"name":"oats","amount":90,"unit":"g"},{"name":"coconut milk","amount":60,"unit":"g"},{"name":"peanut butter","amount":30,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"}]'::jsonb, '["{180} ml water","pinch of salt","pinch of cinnamon"]'::jsonb, '["Stir the oats, coconut milk, water, salt and half the peanut butter together in a jar or bowl","Cover and leave in the fridge overnight, or for at least 4 hours","Stir well, loosen with a splash of water if needed and top with the sliced banana, the remaining peanut butter and cinnamon"]'::jsonb, '[]'::jsonb, '["quick","hearty","oats","coconut milk","peanut butter","banana","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","halal","kosher"]'::jsonb, 46),
  ('b-greek-yogurt-power-bowl', 'Greek Yogurt Power Bowl', 'Big bowl of Greek yogurt with banana, blueberries, peanut butter and honey', 'breakfast', 'greek yogurt', '🫐', 5, 'quick', 654, 34, 73, 28, 6, 54, 214, '[{"name":"greek yogurt","amount":300,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"blueberries","amount":80,"unit":"g"},{"name":"peanut butter","amount":25,"unit":"g"},{"name":"honey","amount":20,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Spoon the yogurt into a bowl","Slice the banana and arrange it on top with the blueberries","Add the peanut butter in small spoonfuls, drizzle with the honey and dust with cinnamon"]'::jsonb, '[]'::jsonb, '["fresh","quick","hearty","greek yogurt","banana","blueberries","peanut butter","honey","breakfast"]'::jsonb, '["vegetarian","gluten-free","halal","kosher"]'::jsonb, 47),
  ('b-cheesy-egg-quesadilla', 'Cheesy Egg and Spinach Quesadilla', 'Crisp tortillas filled with scrambled egg, spinach and melted cheese', 'breakfast', 'eggs', '🧀', 12, 'quick', 748, 37, 63, 38, 5, 6, 1513, '[{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"cheese","amount":50,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Melt the butter in a pan, wilt the spinach for 30 seconds, then pour in the beaten eggs and scramble until just set","Cover one tortilla with half the grated cheese, the eggs and the rest of the cheese, and top with the second tortilla","Wipe out the pan and cook the quesadilla over medium heat for 2 minutes per side until crisp","Cut into wedges"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","tortilla","eggs","cheese","spinach","butter","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 48),
  ('b-banana-pancake-stack', 'Banana Pancake Stack', 'Thick pancakes with banana, butter and honey', 'breakfast', 'flour', '🥞', 25, 'balanced', 750, 29, 109, 23, 5, 36, 297, '[{"name":"flour","amount":80,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"milk","amount":150,"unit":"ml"},{"name":"butter","amount":10,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"honey","amount":15,"unit":"g"}]'::jsonb, '["pinch of salt","pinch of cinnamon"]'::jsonb, '["Whisk the flour, eggs, milk and salt into a smooth, thick batter and rest it for 5 minutes","Melt a little of the butter in a non-stick pan over medium heat","Cook small thick pancakes for about 2 minutes per side until golden, adding butter as needed","Stack them with the sliced banana, drizzle with the honey and dust with cinnamon"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","flour","eggs","milk","butter","banana","honey","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 49),
  ('b-tofu-bean-breakfast-plate', 'Tofu and Bean Breakfast Plate', 'Scrambled tofu with kidney beans, tomato and spinach, and a slice of toast', 'breakfast', 'tofu', '🍳', 12, 'quick', 574, 49, 48, 25, 14, 8, 463, '[{"name":"tofu","amount":200,"unit":"g"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of turmeric","pinch of salt","black pepper"]'::jsonb, '["Heat the oil in a pan over medium heat, crumble in the tofu and fry it with the turmeric, salt and black pepper for 4 minutes","Add the drained beans and the diced tomato and cook for 3 minutes","Stir in the spinach until wilted, and toast the bread meanwhile","Serve the scramble with the toast"]'::jsonb, '["stovetop"]'::jsonb, '["quick","hearty","tofu","kidney beans","tomato","spinach","bread","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 50),
  ('b-breakfast-egg-fried-rice', 'Breakfast Egg Fried Rice', 'Rice fried with scrambled egg, peas and soy sauce', 'breakfast', 'eggs', '🍳', 20, 'quick', 465, 22, 56, 16, 3, 3, 872, '[{"name":"rice","amount":60,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"peas","amount":50,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"ml"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of salt","pinch of white pepper"]'::jsonb, '["Cook the rice in {150} ml of salted water, covered, for 12 minutes","Heat the oil in a pan over medium-high heat, crack in the eggs and scramble them for 1 minute until just set","Add the rice and the peas and fry for 3 minutes, breaking up the rice","Stir in the soy sauce and a little white pepper and serve"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","rice","eggs","peas","soy sauce","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 51),
  ('b-savoury-soy-oats-egg', 'Savoury Oats with Egg and Soy', 'Oats cooked in water with mushrooms and spinach, topped with a fried egg and soy sauce', 'breakfast', 'oats', '🥣', 12, 'quick', 343, 18, 39, 14, 7, 2, 783, '[{"name":"oats","amount":50,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"mushrooms","amount":60,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"ml"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Slice the mushrooms and fry them in half of the oil in a small pot over medium heat for 3 minutes","Add the oats and {250} ml of water and simmer for 4 minutes, stirring, until thick, then stir in the spinach until wilted","Fry the egg in the rest of the oil in a small pan until the white is set","Pour the oats into a bowl, lay the egg on top and drizzle with the soy sauce"]'::jsonb, '["stovetop"]'::jsonb, '["asian","comfort","quick","light","oats","eggs","mushrooms","spinach","soy sauce","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 52),
  ('b-rice-congee-egg', 'Rice Congee with Egg and Mushrooms', 'Rice simmered until soft and silky, with mushrooms, a soft egg and soy sauce', 'breakfast', 'rice', '🍚', 40, 'weekend', 281, 13, 43, 6, 1, 2, 743, '[{"name":"rice","amount":50,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"mushrooms","amount":60,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"ml"}]'::jsonb, '["pinch of salt","a little grated ginger"]'::jsonb, '["Rinse the rice, put it in a pot with {500} ml of water and a pinch of salt and bring to the boil","Turn the heat down and simmer for 30 minutes, stirring now and then, until the rice has broken down into a thick porridge","Slice the mushrooms and add them for the last 5 minutes","Boil the egg for 7 minutes in a separate pot, peel and halve it","Serve the congee with the egg on top, the soy sauce and a little grated ginger"]'::jsonb, '["stovetop"]'::jsonb, '["asian","comfort","light","rice","eggs","mushrooms","soy sauce","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 53),
  ('b-soy-tofu-rice-bowl', 'Soy Tofu Breakfast Rice Bowl', 'Warm rice with golden tofu, wilted spinach and soy sauce', 'breakfast', 'tofu', '🍙', 20, 'quick', 466, 33, 47, 19, 6, 0, 1060, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"rice","amount":50,"unit":"g"},{"name":"spinach","amount":60,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"ml"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of salt"]'::jsonb, '["Cook the rice in {120} ml of salted water, covered, for 12 minutes","Pat the tofu dry and cut it into cubes, then fry it in the oil over medium-high heat for 6 minutes until golden","Add the spinach and the soy sauce and toss for 1 minute until the spinach has wilted","Spoon the tofu and spinach over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","tofu","rice","spinach","soy sauce","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 54),
  ('b-caprese-toast', 'Caprese Toast', 'Toast with mozzarella, sliced tomato and olive oil', 'breakfast', 'mozzarella', '🍅', 5, 'quick', 418, 23, 35, 21, 5, 6, 615, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"mozzarella","amount":60,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of salt","black pepper","pinch of dried oregano"]'::jsonb, '["Toast the bread","Slice the mozzarella and the tomato and layer them on the toast","Drizzle with the olive oil and season with salt, black pepper and a pinch of dried oregano"]'::jsonb, '[]'::jsonb, '["italian","fresh","quick","bread","mozzarella","tomato","olive oil","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 55),
  ('b-zucchini-parmesan-frittata', 'Zucchini and Parmesan Frittata', 'A thick open omelette with zucchini and parmesan, with a slice of toast', 'breakfast', 'eggs', '🥒', 15, 'quick', 448, 32, 20, 26, 3, 5, 580, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"zucchini","amount":120,"unit":"g"},{"name":"parmesan","amount":15,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["pinch of salt","black pepper"]'::jsonb, '["Slice the zucchini thinly and fry it in the olive oil in a small pan over medium heat for 4 minutes until soft","Beat the eggs with the grated parmesan, salt and black pepper and pour them over the zucchini","Cook on low heat for 4 minutes until nearly set, then cover the pan for 2 minutes to set the top","Slide onto a plate and serve with the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","eggs","zucchini","parmesan","olive oil","bread","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 56),
  ('b-pesto-eggs-toast', 'Pesto Eggs on Toast', 'Eggs fried in pesto, on toast with fresh tomato', 'breakfast', 'eggs', '🌿', 8, 'quick', 412, 24, 35, 19, 5, 6, 628, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"pesto","amount":15,"unit":"ml"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Warm the pesto in a pan over medium heat until it sizzles","Crack in the eggs and fry them for 3 minutes until the whites are set, spooning the pesto over them","Toast the bread, slice the tomato and lay it on the toast","Top with the eggs and season with black pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","eggs","pesto","bread","tomato","stovetop","breakfast"]'::jsonb, '["vegetarian","halal","kosher"]'::jsonb, 57),
  ('b-tomato-chickpea-bruschetta', 'Tomato and Chickpea Bruschetta', 'Garlic-rubbed toast piled with tomato and chickpeas in olive oil', 'breakfast', 'chickpeas', '🥖', 8, 'quick', 414, 17, 58, 14, 12, 10, 571, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"chickpeas","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"}]'::jsonb, '["pinch of salt","black pepper","pinch of dried oregano"]'::jsonb, '["Dice the tomato and mix it with the drained chickpeas, the olive oil, a pinch of salt and black pepper, lightly crushing some of the chickpeas with a fork","Toast the bread and rub it with the cut side of the halved garlic","Pile the tomato and chickpeas on the toast and finish with a pinch of dried oregano"]'::jsonb, '[]'::jsonb, '["italian","fresh","quick","bread","chickpeas","tomato","olive oil","garlic","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 58),
  ('b-soft-egg-bruschetta', 'Bruschetta with Soft Eggs', 'Tomato bruschetta topped with soft-boiled eggs', 'breakfast', 'eggs', '🥚', 12, 'quick', 437, 24, 38, 21, 6, 7, 483, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"tomato","amount":150,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"}]'::jsonb, '["pinch of salt","black pepper"]'::jsonb, '["Boil the eggs for 6 minutes, cool them under cold water and peel them","Dice the tomato and toss it with the olive oil, salt and black pepper","Toast the bread, rub it with the cut side of the halved garlic and spoon the tomato on top","Halve the eggs and lay them on the bruschetta"]'::jsonb, '["stovetop"]'::jsonb, '["italian","fresh","quick","bread","eggs","tomato","olive oil","garlic","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 59),
  ('d-chicken-teriyaki-stir-fry', 'Chicken Teriyaki Stir-Fry', 'Chicken, broccoli and peppers in teriyaki sauce over rice', 'dinner', 'chicken', '🍗', 25, 'balanced', 670, 48, 83, 15, 6, 11, 1652, '[{"name":"chicken","amount":160,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"broccoli","amount":120,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"teriyaki","amount":40,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp grated ginger"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the chicken and stir-fry it in the oil over high heat for 5 minutes until browned","Add the broccoli florets, sliced peppers, ginger and a splash of water and cook for 4 minutes","Pour in the teriyaki, toss for 1 minute until glossy and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","chicken","rice","broccoli","peppers","teriyaki","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 60),
  ('d-beef-broccoli-stir-fry', 'Beef and Broccoli Stir-Fry', 'Tender beef strips and broccoli in a garlic soy sauce with rice', 'dinner', 'beef', '🥩', 25, 'balanced', 754, 49, 94, 20, 6, 3, 1244, '[{"name":"beef","amount":160,"unit":"g"},{"name":"rice","amount":100,"unit":"g"},{"name":"broccoli","amount":150,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"soy sauce","amount":20,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp grated ginger","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the beef thinly against the grain and sear it in half the oil over very high heat for 2 minutes, then set it aside","Stir-fry the broccoli florets in the remaining oil with a splash of water for 4 minutes","Return the beef with the chopped garlic, ginger and soy sauce, toss for 1 minute and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","hearty","beef","rice","broccoli","garlic","soy sauce","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 61),
  ('d-thai-coconut-chicken-curry', 'Thai Coconut Chicken Curry', 'Chicken, peppers and green beans in a spicy coconut sauce with rice', 'dinner', 'chicken', '🍛', 30, 'balanced', 814, 45, 81, 35, 6, 8, 97, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"coconut milk","amount":120,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"green beans","amount":80,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp red curry paste","squeeze of lime juice","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the onion and soften it in the oil for 3 minutes, then fry the curry paste with it for 1 minute","Add the chicken in bite-sized pieces and cook for 3 minutes, then pour in the coconut milk","Add the sliced peppers and halved green beans and simmer for 10 minutes until the chicken is cooked and the beans are tender","Finish with lime juice and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","comfort","hearty","chicken","coconut milk","rice","peppers","green beans","onion","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 62),
  ('d-garlic-shrimp-noodles', 'Garlic Shrimp Noodles', 'Stir-fried noodles with shrimp, zucchini, carrot and plenty of garlic', 'dinner', 'shrimp', '🍤', 15, 'quick', 638, 48, 74, 17, 6, 7, 1248, '[{"name":"shrimp","amount":160,"unit":"g"},{"name":"noodles","amount":85,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"soy sauce","amount":18,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["black pepper","squeeze of lime juice"]'::jsonb, '["Cook the noodles according to the packet, drain and rinse briefly","Cut the zucchini and carrots into thin strips and stir-fry them in the oil over high heat for 3 minutes","Add the shrimp and sliced garlic and cook for 2 to 3 minutes until the shrimp turn pink","Toss in the noodles and soy sauce, heat through and finish with pepper and lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","shrimp","noodles","zucchini","carrots","garlic","soy sauce","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, 63),
  ('d-tofu-coconut-curry', 'Tofu Coconut Curry', 'Tofu, spinach and peppers in a spiced coconut sauce with rice', 'dinner', 'tofu', '🥥', 25, 'balanced', 829, 42, 79, 43, 9, 5, 110, '[{"name":"tofu","amount":180,"unit":"g"},{"name":"coconut milk","amount":100,"unit":"g"},{"name":"rice","amount":75,"unit":"g"},{"name":"spinach","amount":80,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry paste","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the onion and peppers and cook them in the oil for 4 minutes, then stir in the curry paste for 1 minute","Add the coconut milk and the tofu, cut into cubes, and simmer gently for 8 minutes","Stir in the spinach until wilted, season with salt and lime juice and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","comfort","hearty","tofu","coconut milk","rice","spinach","peppers","onion","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 64),
  ('d-pork-fried-rice', 'Pork Fried Rice', 'Fried rice with pork, egg, peas and carrot', 'dinner', 'pork', '🍚', 25, 'balanced', 787, 48, 86, 26, 6, 7, 1245, '[{"name":"pork","amount":140,"unit":"g"},{"name":"rice","amount":85,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"peas","amount":60,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"soy sauce","amount":18,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it steam dry","Cut the pork into small strips and fry in the oil over high heat for 4 minutes until browned","Add the diced onion and carrots and the peas and stir-fry for 3 minutes","Push everything aside, scramble the egg in the gap, then add the rice and soy sauce and fry for 2 minutes"]'::jsonb, '["stovetop"]'::jsonb, '["asian","hearty","pork","rice","eggs","peas","carrots","onion","soy sauce","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, 65),
  ('d-teriyaki-salmon-green-beans', 'Teriyaki Salmon with Green Beans', 'Oven-glazed salmon with green beans and rice', 'dinner', 'salmon', '🐟', 25, 'balanced', 721, 41, 79, 26, 4, 10, 1633, '[{"name":"salmon","amount":150,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"teriyaki","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["sesame seeds if you have them"]'::jsonb, '["Heat the oven to 200°C and boil the rice in salted water for 10 to 12 minutes, then drain","Toss the green beans with the oil on a baking tray, put the salmon next to them and brush it with half the teriyaki","Roast for 12 minutes until the salmon flakes easily","Brush the salmon with the remaining teriyaki and serve with the beans and rice"]'::jsonb, '["stovetop","oven"]'::jsonb, '["asian","salmon","rice","green beans","teriyaki","oil","stovetop","oven","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 66),
  ('d-chicken-chow-mein', 'Chicken Chow Mein', 'Stir-fried noodles with chicken, carrot, peppers and onion', 'dinner', 'chicken', '🍜', 20, 'quick', 679, 49, 75, 20, 7, 9, 1229, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"noodles","amount":85,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"soy sauce","amount":20,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp grated ginger","black pepper"]'::jsonb, '["Cook the noodles according to the packet, drain and rinse briefly","Slice the chicken thinly and stir-fry it in the oil over high heat for 4 minutes","Add the sliced onion, peppers and carrots and the ginger and cook for 3 minutes","Add the noodles and soy sauce and toss over the heat for 2 minutes"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","chicken","noodles","carrots","peppers","onion","soy sauce","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 67),
  ('d-spicy-beef-green-bean-rice', 'Spicy Beef and Green Bean Rice Bowl', 'Chili-garlic beef mince with blistered green beans over rice', 'dinner', 'beef mince', '🌶️', 20, 'quick', 717, 38, 76, 28, 5, 4, 1100, '[{"name":"beef mince","amount":150,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"soy sauce","amount":18,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp chili flakes","1 tsp grated ginger"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Fry the green beans, cut into short lengths, in the oil over high heat for 4 minutes until blistered, then set aside","Brown the beef mince in the same pan for 5 minutes, then add the chopped garlic, ginger and chili flakes","Return the beans, add the soy sauce, toss for 1 minute and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","quick","beef mince","rice","green beans","garlic","soy sauce","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 68),
  ('d-turkey-zucchini-stir-fry', 'Turkey and Zucchini Stir-Fry', 'Lean turkey mince stir-fried with zucchini and carrot, served with rice', 'dinner', 'turkey mince', '🥒', 20, 'quick', 600, 38, 66, 21, 4, 7, 969, '[{"name":"turkey mince","amount":150,"unit":"g"},{"name":"rice","amount":65,"unit":"g"},{"name":"zucchini","amount":150,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp grated ginger","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Brown the turkey mince in the oil over high heat for 5 minutes, breaking it up","Add the zucchini in half-moons, the carrots in thin strips, the chopped garlic and the ginger and stir-fry for 4 minutes","Stir in the soy sauce and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","turkey mince","rice","zucchini","carrots","soy sauce","garlic","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 69),
  ('d-vegetable-egg-fried-rice', 'Vegetable Egg Fried Rice', 'Big bowl of fried rice with three eggs, peas, corn and carrot', 'dinner', 'eggs', '🍳', 20, 'quick', 770, 34, 92, 29, 7, 9, 1440, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"rice","amount":85,"unit":"g"},{"name":"peas","amount":70,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"soy sauce","amount":18,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it steam dry","Dice the carrots and fry them in the oil over high heat for 3 minutes, then add the peas and corn","Push the vegetables aside, crack in the eggs and scramble until just set","Add the rice and soy sauce and stir-fry for 2 to 3 minutes"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","hearty","eggs","rice","peas","corn","carrots","soy sauce","oil","stovetop","dinner"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 70),
  ('d-soy-ginger-fish', 'Soy-Ginger Fish with Rice', 'Gently steamed white fish with spinach, carrot and a soy-ginger sauce', 'dinner', 'white fish', '🐟', 20, 'quick', 507, 40, 69, 7, 5, 3, 1041, '[{"name":"white fish","amount":170,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"spinach","amount":100,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp grated ginger","3 tbsp water"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Warm the oil in a lidded pan and soften the sliced garlic, ginger and thinly sliced carrots for 2 minutes","Lay the fish on top, add the soy sauce and water, cover and steam over low heat for 6 to 8 minutes","Add the spinach for the last minute and serve everything over the rice with the pan juices"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","white fish","rice","spinach","carrots","soy sauce","garlic","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 71),
  ('d-coconut-lentil-dal', 'Coconut Lentil Dal', 'Creamy spiced lentils with tomato, spinach and coconut, served with rice', 'dinner', 'lentils', '🍲', 35, 'balanced', 777, 30, 116, 24, 15, 8, 257, '[{"name":"lentils","amount":80,"unit":"g"},{"name":"coconut milk","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"spinach","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"rice","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","1/2 tsp chili flakes","{350} ml water","salt"]'::jsonb, '["Dice the onion and soften it in the oil for 4 minutes, then add the chopped garlic, curry powder and chili flakes for 1 minute","Add the rinsed lentils, chopped tomatoes and water and simmer for 20 to 25 minutes until the lentils are soft","Meanwhile boil the rice in salted water for 10 to 12 minutes and drain","Stir the coconut milk and spinach into the lentils, cook 2 more minutes, season with salt and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","comfort","hearty","lentils","coconut milk","chopped tomatoes","spinach","onion","garlic","rice","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 72),
  ('d-chili-con-carne', 'Chili con Carne', 'Slow-simmered beef and bean chili with rice', 'dinner', 'beef mince', '🌶️', 40, 'balanced', 848, 45, 100, 30, 13, 14, 570, '[{"name":"beef mince","amount":150,"unit":"g"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"rice","amount":75,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","salt"]'::jsonb, '["Soften the diced onion and peppers in the oil for 5 minutes, then add the beef mince and brown it for 5 minutes","Stir in the chopped garlic, cumin, paprika and chili flakes for 1 minute","Add the chopped tomatoes and drained kidney beans and simmer gently for 20 minutes until thick","Meanwhile boil the rice in salted water for 10 to 12 minutes, drain and serve with the chili"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","hearty","beef mince","kidney beans","chopped tomatoes","onion","peppers","rice","garlic","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 73),
  ('d-chicken-enchiladas', 'Chicken Enchiladas', 'Tortillas rolled around chicken and peppers, baked in tomato sauce with cheese', 'dinner', 'chicken', '🫔', 40, 'balanced', 810, 55, 81, 30, 9, 17, 1320, '[{"name":"chicken","amount":140,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"tomato sauce","amount":150,"unit":"g"},{"name":"cheese","amount":40,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt"]'::jsonb, '["Heat the oven to 200°C","Fry the chicken in small pieces with the diced onion and peppers in the oil for 7 minutes, then stir in the cumin, paprika, salt and a third of the tomato sauce","Divide the filling between the tortillas, roll them up and place them seam side down in a small baking dish","Pour over the remaining tomato sauce, scatter with the grated cheese and bake for 15 minutes until bubbling"]'::jsonb, '["stovetop","oven"]'::jsonb, '["mexican","comfort","hearty","chicken","tortilla","tomato sauce","cheese","onion","peppers","oil","stovetop","oven","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 74),
  ('d-beef-bean-burritos', 'Beef and Bean Burritos', 'Tortillas filled with spiced beef mince, kidney beans, cheese and tomato', 'dinner', 'beef mince', '🌯', 25, 'balanced', 862, 48, 83, 37, 10, 11, 1363, '[{"name":"beef mince","amount":130,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"cheese","amount":25,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"onion","amount":40,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt"]'::jsonb, '["Brown the beef mince with the diced onion in a dry pan over high heat for 6 minutes","Add the cumin, paprika, salt, the drained kidney beans and a splash of water and cook for 3 minutes","Warm the tortillas in a dry pan","Fill them with the beef and beans, grated cheese and diced tomato, fold in the sides and roll up tightly"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","hearty","beef mince","tortilla","kidney beans","cheese","tomato","onion","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 75),
  ('d-fish-tacos', 'Fish Tacos', 'Pan-fried white fish in tortillas with lettuce, tomato and a lime yogurt sauce', 'dinner', 'white fish', '🐟', 20, 'quick', 625, 43, 66, 20, 6, 9, 1001, '[{"name":"white fish","amount":170,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp paprika","1/2 tsp ground cumin","salt","squeeze of lime juice"]'::jsonb, '["Season the fish with the paprika, cumin and salt and fry in the oil over medium-high heat for 3 minutes per side, then break into large flakes","Stir lime juice and a pinch of salt into the yogurt","Warm the tortillas in a dry pan","Fill them with shredded lettuce, the fish and diced tomato and drizzle with the yogurt sauce"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","fresh","quick","light","white fish","tortilla","lettuce","tomato","yogurt","oil","stovetop","dinner"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, 76),
  ('d-sweet-potato-bean-chili', 'Sweet Potato and Bean Chili', 'Thick vegan chili with sweet potato, kidney beans, peppers and corn', 'dinner', 'kidney beans', '🍠', 35, 'balanced', 539, 19, 97, 11, 22, 27, 795, '[{"name":"sweet potato","amount":200,"unit":"g"},{"name":"kidney beans","amount":150,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp smoked paprika","1/2 tsp chili flakes","{150} ml water","salt"]'::jsonb, '["Soften the diced onion and peppers in the oil for 5 minutes, then stir in the cumin, paprika and chili flakes","Add the sweet potato in 2 cm cubes, the chopped tomatoes and the water and simmer, covered, for 20 minutes until the sweet potato is tender","Stir in the drained kidney beans and corn and cook for 5 more minutes","Season with salt"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","light","sweet potato","kidney beans","chopped tomatoes","onion","peppers","corn","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 77),
  ('d-loaded-chicken-burrito-bowl', 'Loaded Chicken Burrito Bowl', 'Rice bowl with spiced chicken, beans, corn, tomato and avocado', 'dinner', 'chicken', '🥑', 25, 'balanced', 906, 53, 105, 32, 17, 9, 398, '[{"name":"chicken","amount":160,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":80,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Coat the chicken, cut into strips, with the cumin, paprika and salt and fry in the oil for 7 minutes until cooked through","Warm the drained kidney beans and corn in the pan for 1 minute","Serve the rice topped with the chicken, beans, corn, diced tomato and sliced avocado, with lime juice squeezed over"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","hearty","chicken","rice","kidney beans","corn","avocado","tomato","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 78),
  ('d-pork-tacos-corn-salsa', 'Pork Tacos with Corn Salsa', 'Seared pork strips in tortillas with a fresh corn and tomato salsa', 'dinner', 'pork', '🌮', 20, 'quick', 719, 44, 74, 27, 7, 10, 1089, '[{"name":"pork","amount":150,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"corn","amount":60,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Mix the corn with the diced tomato, finely diced onion, lime juice and a pinch of salt","Cut the pork into thin strips and coat with the cumin, paprika and salt","Fry the pork in the oil over high heat for 4 to 5 minutes until browned and cooked through","Warm the tortillas and fill them with the pork and salsa"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","pork","tortilla","corn","tomato","onion","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, 79),
  ('d-shrimp-fajitas', 'Shrimp Fajitas', 'Sizzling shrimp with peppers and onion in warm tortillas', 'dinner', 'shrimp', '🍤', 15, 'quick', 638, 46, 72, 19, 8, 12, 1093, '[{"name":"shrimp","amount":170,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"peppers","amount":120,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","salt","squeeze of lime juice"]'::jsonb, '["Slice the peppers and onion and fry them in the oil over high heat for 5 minutes until soft and charred at the edges","Add the shrimp with the cumin, paprika, chili flakes and salt and cook for 2 to 3 minutes until pink","Warm the tortillas in a dry pan","Fill them with the shrimp and vegetables and squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","light","shrimp","tortilla","peppers","onion","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, 80),
  ('d-turkey-bean-chili', 'Turkey and Bean Chili', 'Lean turkey mince chili with kidney beans and peppers, served with rice', 'dinner', 'turkey mince', '🦃', 35, 'balanced', 682, 45, 86, 19, 13, 14, 556, '[{"name":"turkey mince","amount":150,"unit":"g"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","salt"]'::jsonb, '["Soften the diced onion and peppers in the oil for 5 minutes, then add the turkey mince and brown it for 5 minutes","Stir in the cumin, paprika and chili flakes, then the chopped tomatoes and drained kidney beans","Simmer for 15 minutes until thick and season with salt","Meanwhile boil the rice in salted water for 10 to 12 minutes, drain and serve with the chili"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","turkey mince","kidney beans","chopped tomatoes","peppers","onion","rice","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 81),
  ('d-mexican-stuffed-peppers', 'Mexican Stuffed Peppers', 'Peppers filled with mince, rice and corn, baked with cheese', 'dinner', 'mixed mince', '🫑', 50, 'weekend', 705, 37, 70, 32, 8, 17, 456, '[{"name":"peppers","amount":250,"unit":"g"},{"name":"mixed mince","amount":120,"unit":"g"},{"name":"rice","amount":50,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"tomato sauce","amount":80,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt"]'::jsonb, '["Heat the oven to 200°C and boil the rice in salted water for 10 minutes, then drain","Brown the mince in a dry pan for 5 minutes and stir in the cumin, paprika, salt, corn, rice and tomato sauce","Halve the peppers lengthways and scoop out the seeds. Fill the pepper halves with the mixture","Place in a baking dish, cover with foil and bake for 20 minutes, then uncover, top with the grated cheese and bake 10 more minutes"]'::jsonb, '["stovetop","oven"]'::jsonb, '["mexican","comfort","peppers","mixed mince","rice","corn","cheese","tomato sauce","stovetop","oven","dinner"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, 82),
  ('d-tofu-bean-tacos', 'Tofu and Bean Tacos', 'Crumbled spiced tofu and kidney beans in tortillas with tomato and lettuce', 'dinner', 'tofu', '🌮', 20, 'quick', 774, 43, 85, 32, 14, 10, 1096, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"lettuce","amount":40,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp smoked paprika","1/2 tsp chili flakes","salt","squeeze of lime juice"]'::jsonb, '["Crumble the tofu into the hot oil and fry over medium-high heat for 6 minutes until golden","Add the cumin, paprika, chili flakes, salt and drained kidney beans and cook for 2 minutes","Warm the tortillas in a dry pan","Fill them with the tofu and beans, diced tomato and shredded lettuce and finish with lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","hearty","tofu","tortilla","kidney beans","tomato","lettuce","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 83),
  ('d-chicken-quesadillas', 'Chicken Quesadillas', 'Crisp tortillas with chicken, peppers and melted cheese, with fresh tomato', 'dinner', 'chicken', '🧀', 25, 'balanced', 775, 53, 67, 32, 6, 10, 1358, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"cheese","amount":50,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp paprika","1/2 tsp ground cumin","salt"]'::jsonb, '["Cut the chicken into small pieces, season with the paprika, cumin and salt and fry in the oil for 6 minutes with the diced peppers","Cover one tortilla with half the grated cheese, the chicken and peppers and the rest of the cheese, then top with the second tortilla","Cook in a clean dry pan over medium heat for 3 minutes per side until golden and melted","Cut into wedges and serve with the diced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","hearty","chicken","tortilla","cheese","peppers","tomato","oil","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 84),
  ('d-beef-burrito-salad-bowl', 'Beef Burrito Salad Bowl', 'Seared beef over lettuce with rice, beans, corn, tomato and avocado', 'dinner', 'beef', '🥗', 25, 'balanced', 782, 48, 76, 34, 18, 10, 415, '[{"name":"beef","amount":150,"unit":"g"},{"name":"lettuce","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"rice","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it cool a little","Rub the beef with the cumin, paprika and salt and sear it in the oil over high heat for 2 to 3 minutes per side, then rest it for 3 minutes and slice thinly","Shred the lettuce and dice the tomato and avocado","Build the bowl with the lettuce, rice, drained kidney beans, corn, tomato and avocado, top with the beef and squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","fresh","hearty","beef","lettuce","tomato","corn","kidney beans","avocado","rice","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 85),
  ('d-spaghetti-bolognese', 'Spaghetti Bolognese', 'Classic beef and tomato ragù with spaghetti and parmesan', 'dinner', 'beef mince', '🍝', 45, 'weekend', 829, 44, 87, 33, 9, 12, 483, '[{"name":"beef mince","amount":140,"unit":"g"},{"name":"pasta","amount":90,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"parmesan","amount":10,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 6 minutes","Add the beef mince and brown it well for 6 minutes, then stir in the chopped garlic and oregano","Add the chopped tomatoes, season and simmer gently for 25 minutes, adding a splash of water if it gets too thick","Cook the pasta in salted boiling water, drain, toss with the sauce and serve with the grated parmesan"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","hearty","beef mince","pasta","chopped tomatoes","onion","carrots","garlic","olive oil","parmesan","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 86),
  ('d-creamy-chicken-mushroom-pasta', 'Creamy Chicken and Mushroom Pasta', 'Pasta in a garlic cream sauce with chicken, mushrooms and parmesan', 'dinner', 'chicken', '🍄', 25, 'balanced', 769, 54, 73, 28, 4, 7, 254, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"pasta","amount":85,"unit":"g"},{"name":"mushrooms","amount":100,"unit":"g"},{"name":"cream sauce","amount":80,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"parmesan","amount":10,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a little of the water","Fry the chicken in strips in the oil over medium-high heat for 5 minutes, then add the sliced mushrooms for 4 minutes","Add the chopped garlic, then the cream sauce and a splash of pasta water and simmer for 2 minutes","Toss in the pasta and parmesan and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","hearty","chicken","pasta","mushrooms","cream sauce","garlic","parmesan","oil","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 87),
  ('d-pesto-salmon-potatoes', 'Pesto Salmon with Potatoes and Green Beans', 'Baked salmon with a pesto crust, boiled potatoes and green beans', 'dinner', 'salmon', '🐟', 30, 'balanced', 627, 39, 53, 29, 9, 6, 310, '[{"name":"salmon","amount":150,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"pesto","amount":20,"unit":"g"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Heat the oven to 200°C and boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the green beans for the last 5","Put the salmon on a lined tray, spread the pesto over the top and bake for 12 minutes","Drain the potatoes and beans and season them","Serve with the salmon and a squeeze of lemon"]'::jsonb, '["stovetop","oven"]'::jsonb, '["italian","light","salmon","potatoes","green beans","pesto","stovetop","oven","dinner"]'::jsonb, '["gluten-free","halal","kosher"]'::jsonb, 88),
  ('d-pork-ragu-penne', 'Pork Ragù with Penne', 'Rich pork mince and tomato sauce with penne', 'dinner', 'pork mince', '🍝', 40, 'balanced', 782, 36, 82, 34, 9, 11, 339, '[{"name":"pork mince","amount":130,"unit":"g"},{"name":"pasta","amount":85,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"carrots","amount":40,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","pinch of fennel seeds","salt","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 5 minutes","Add the pork mince and brown it for 6 minutes, then add the chopped garlic, oregano and fennel seeds","Add the chopped tomatoes and simmer for 20 minutes","Cook the pasta in salted boiling water, drain and toss with the ragù"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","hearty","pork mince","pasta","chopped tomatoes","onion","carrots","garlic","olive oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, 89),
  ('d-lentil-bolognese', 'Lentil Bolognese', 'Hearty vegan lentil and tomato sauce with pasta', 'dinner', 'lentils', '🍝', 40, 'balanced', 738, 32, 127, 13, 17, 14, 284, '[{"name":"lentils","amount":75,"unit":"g"},{"name":"pasta","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","{300} ml water","salt","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 5 minutes, then add the chopped garlic and oregano","Add the rinsed lentils, chopped tomatoes and water and simmer for 25 minutes until the lentils are tender and the sauce is thick","Cook the pasta in salted boiling water and drain","Season the sauce and serve over the pasta"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","lentils","pasta","chopped tomatoes","carrots","onion","garlic","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 90),
  ('d-chicken-parmesan-bake', 'Chicken Parmesan Bake', 'Chicken baked in tomato sauce under mozzarella and parmesan, with pasta', 'dinner', 'chicken', '🧀', 40, 'balanced', 800, 66, 67, 29, 5, 9, 542, '[{"name":"chicken","amount":170,"unit":"g"},{"name":"tomato sauce","amount":150,"unit":"g"},{"name":"mozzarella","amount":50,"unit":"g"},{"name":"parmesan","amount":15,"unit":"g"},{"name":"pasta","amount":70,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Heat the oven to 200°C, season the chicken and brown it in the olive oil for 2 minutes per side","Put it in a small baking dish, pour over the tomato sauce mixed with the oregano and top with the sliced mozzarella and grated parmesan","Bake for 20 minutes until the chicken is cooked through and the cheese is golden","Meanwhile cook the pasta in salted boiling water, drain and serve with the chicken and its sauce"]'::jsonb, '["stovetop","oven"]'::jsonb, '["italian","comfort","hearty","chicken","tomato sauce","mozzarella","parmesan","pasta","olive oil","stovetop","oven","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 91),
  ('d-shrimp-arrabbiata', 'Shrimp Arrabbiata', 'Spaghetti with shrimp in a spicy garlic tomato sauce', 'dinner', 'shrimp', '🌶️', 20, 'quick', 626, 46, 78, 15, 7, 8, 428, '[{"name":"shrimp","amount":160,"unit":"g"},{"name":"pasta","amount":90,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp chili flakes","salt","handful of fresh parsley"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain","Gently fry the sliced garlic and chili flakes in the olive oil for 1 minute","Add the chopped tomatoes and simmer for 8 minutes","Add the shrimp and cook for 3 minutes until pink, then toss with the pasta and parsley"]'::jsonb, '["stovetop"]'::jsonb, '["italian","spicy","quick","light","shrimp","pasta","chopped tomatoes","garlic","olive oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, 92),
  ('d-chicken-mushroom-risotto', 'Chicken and Mushroom Risotto', 'Creamy rice with chicken, mushrooms, peas and parmesan', 'dinner', 'chicken', '🍚', 40, 'balanced', 747, 51, 92, 19, 6, 8, 492, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"rice","amount":90,"unit":"g"},{"name":"mushrooms","amount":150,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"parmesan","amount":25,"unit":"g"},{"name":"butter","amount":10,"unit":"g"},{"name":"peas","amount":60,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"}]'::jsonb, '["1 stock cube","{600} ml hot water","black pepper"]'::jsonb, '["Melt half the butter in a wide pan and cook the chicken in small pieces with the diced onion and sliced mushrooms for 6 minutes","Add the chopped garlic and rice and stir for 1 minute","Dissolve the stock cube in the hot water and add it a ladle at a time, stirring often, for about 20 minutes until the rice is creamy and just tender","Stir in the peas for the last 3 minutes, then the remaining butter and the grated parmesan, and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","chicken","rice","mushrooms","onion","parmesan","butter","peas","garlic","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 93),
  ('d-eggs-in-purgatory', 'Eggs in Purgatory', 'Eggs baked in a spicy garlic tomato sauce, with bread for dipping', 'dinner', 'eggs', '🍅', 20, 'quick', 611, 37, 43, 32, 9, 10, 1018, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"chopped tomatoes","amount":250,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"parmesan","amount":15,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","salt","pinch of dried oregano"]'::jsonb, '["Gently fry the sliced garlic and chili flakes in the olive oil for 1 minute","Add the chopped tomatoes, oregano and salt and simmer for 8 minutes until thickened","Make {n:eggs} wells, crack in the eggs, cover and cook for 4 to 5 minutes until the whites are set","Scatter with the grated parmesan and serve with the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["italian","spicy","quick","light","eggs","chopped tomatoes","garlic","parmesan","bread","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 94),
  ('d-turkey-meatballs-pasta', 'Turkey Meatballs in Tomato Sauce', 'Tender turkey meatballs simmered in tomato sauce, with pasta and parmesan', 'dinner', 'turkey mince', '🍝', 35, 'balanced', 734, 49, 81, 24, 7, 13, 268, '[{"name":"turkey mince","amount":160,"unit":"g"},{"name":"pasta","amount":80,"unit":"g"},{"name":"tomato sauce","amount":180,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"},{"name":"parmesan","amount":10,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Mix the turkey mince with the finely chopped garlic, half the oregano, salt and pepper and roll into {8} small balls","Brown the meatballs in the olive oil for 5 minutes, then add the diced onion for 2 minutes","Pour in the tomato sauce with the remaining oregano and simmer, covered, for 12 minutes","Cook the pasta in salted boiling water, drain and serve with the meatballs, sauce and grated parmesan"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","turkey mince","pasta","tomato sauce","onion","garlic","parmesan","olive oil","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 95),
  ('d-tuna-pasta-bake', 'Tuna Pasta Bake', 'Creamy baked pasta with tuna, corn and peas under a cheese crust', 'dinner', 'tuna', '🧀', 35, 'balanced', 753, 48, 81, 27, 6, 11, 761, '[{"name":"tuna","amount":120,"unit":"g"},{"name":"pasta","amount":85,"unit":"g"},{"name":"cream sauce","amount":80,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Heat the oven to 200°C and cook the pasta in salted boiling water for 2 minutes less than the packet says, then drain","Mix the pasta with the drained tuna, cream sauce, corn and peas and season","Tip into a small baking dish and scatter over the grated cheese","Bake for 15 minutes until golden and bubbling"]'::jsonb, '["stovetop","oven"]'::jsonb, '["italian","comfort","hearty","tuna","pasta","cream sauce","corn","peas","cheese","stovetop","oven","dinner"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, 96),
  ('d-chickpea-spinach-pasta', 'Chickpea and Spinach Pasta', 'Garlicky tomato pasta with chickpeas and wilted spinach', 'dinner', 'chickpeas', '🍝', 20, 'quick', 631, 24, 102, 16, 16, 12, 578, '[{"name":"chickpeas","amount":130,"unit":"g"},{"name":"pasta","amount":80,"unit":"g"},{"name":"spinach","amount":100,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["pinch of dried oregano","salt","black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain","Gently fry the sliced garlic in the olive oil for 1 minute, then add the chopped tomatoes, drained chickpeas and oregano","Simmer for 8 minutes, then stir in the spinach until wilted","Toss with the pasta and season"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","light","chickpeas","pasta","spinach","chopped tomatoes","garlic","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 97),
  ('d-greek-chicken-traybake', 'Greek Chicken Traybake', 'Chicken roasted with potatoes, zucchini, peppers and lemon, finished with feta', 'dinner', 'chicken', '🍋', 45, 'weekend', 679, 51, 68, 24, 11, 10, 450, '[{"name":"chicken","amount":170,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"zucchini","amount":120,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"feta","amount":30,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["2 tsp dried oregano","salt","black pepper"]'::jsonb, '["Heat the oven to 210°C","Cut the potatoes into small wedges and toss them on a tray with half the olive oil, salt and half the oregano, then roast for 15 minutes","Add the chicken, the zucchini and peppers in chunks, the remaining olive oil and oregano and the lemon cut into wedges","Roast for 20 more minutes until the chicken is cooked through, then crumble over the feta"]'::jsonb, '["oven"]'::jsonb, '["mediterranean","chicken","potatoes","zucchini","peppers","feta","olive oil","lemon","oven","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 98),
  ('d-baked-fish-tomato-potatoes', 'Baked Fish with Tomatoes and Potatoes', 'White fish baked on sliced potatoes with tomato, onion and garlic', 'dinner', 'white fish', '🐟', 40, 'balanced', 544, 40, 66, 14, 9, 8, 126, '[{"name":"white fish","amount":180,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"tomato","amount":150,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper","handful of fresh parsley"]'::jsonb, '["Heat the oven to 200°C","Slice the potatoes and onion thinly, toss with the olive oil, sliced garlic, salt and oregano and spread in a baking dish","Bake for 20 minutes until almost tender","Lay the sliced tomato and the fish on top, season and bake for 12 more minutes, then scatter with parsley"]'::jsonb, '["oven"]'::jsonb, '["mediterranean","light","white fish","potatoes","tomato","onion","garlic","olive oil","oven","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 99),
  ('d-beef-kofta-couscous', 'Beef Kofta with Couscous', 'Spiced beef kofta with couscous, cucumber-tomato salad and yogurt', 'dinner', 'beef mince', '🍢', 25, 'balanced', 709, 41, 65, 31, 5, 8, 149, '[{"name":"beef mince","amount":150,"unit":"g"},{"name":"couscous","amount":70,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"yogurt","amount":80,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","{90} ml boiling water","salt"]'::jsonb, '["Mix the beef mince with the cumin, paprika, chili flakes and salt and shape into {4} short sausages","Fry them in the olive oil over medium-high heat for 8 to 10 minutes, turning, until cooked through","Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Serve the kofta on the couscous with the diced cucumber and tomato and the yogurt"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","beef mince","couscous","cucumber","tomato","yogurt","olive oil","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 100),
  ('d-spanish-chickpea-spinach-stew', 'Spanish Chickpea and Spinach Stew', 'Garlicky chickpeas and spinach in a smoky tomato sauce, with bread', 'dinner', 'chickpeas', '🥘', 25, 'balanced', 569, 25, 79, 20, 22, 16, 947, '[{"name":"chickpeas","amount":200,"unit":"g"},{"name":"spinach","amount":150,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"olive oil","amount":12,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["1 tsp smoked paprika","1/2 tsp ground cumin","1/2 tsp chili flakes","salt"]'::jsonb, '["Dice the onion and soften it in the olive oil for 4 minutes, then add the sliced garlic, paprika, cumin and chili flakes for 1 minute","Add the chopped tomatoes and drained chickpeas and simmer for 10 minutes","Stir in the spinach a handful at a time until it wilts and season with salt","Serve with the bread"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","comfort","light","chickpeas","spinach","chopped tomatoes","onion","garlic","olive oil","bread","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 101),
  ('d-lemon-herb-salmon-couscous', 'Lemon Herb Salmon with Couscous', 'Pan-fried salmon with lemon couscous and green beans', 'dinner', 'salmon', '🐟', 20, 'quick', 682, 42, 64, 29, 8, 5, 104, '[{"name":"salmon","amount":150,"unit":"g"},{"name":"couscous","amount":65,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp dried oregano","{85} ml boiling water","salt","black pepper"]'::jsonb, '["Boil the green beans in salted water for 5 minutes and drain","Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes, then fluff and stir in half the juice of the lemon","Season the salmon with the oregano, salt and pepper and fry in the olive oil for 3 to 4 minutes per side","Serve the salmon on the couscous with the beans and the rest of the lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","salmon","couscous","green beans","olive oil","lemon","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 102),
  ('d-harissa-chicken-chickpeas', 'Harissa Chicken with Chickpeas and Couscous', 'Spicy chicken with peppers and chickpeas over couscous', 'dinner', 'chicken', '🌶️', 30, 'balanced', 775, 54, 93, 20, 13, 9, 331, '[{"name":"chicken","amount":160,"unit":"g"},{"name":"chickpeas","amount":100,"unit":"g"},{"name":"couscous","amount":80,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1 tbsp harissa paste","{100} ml boiling water","salt","squeeze of lemon juice"]'::jsonb, '["Coat the chicken, cut into chunks, with the harissa and a pinch of salt","Fry the sliced onion and peppers in the olive oil for 4 minutes, add the chicken and cook for 7 minutes until browned and cooked through","Add the drained chickpeas and warm through for 2 minutes","Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes, fluff and serve under the chicken with lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","hearty","chicken","chickpeas","couscous","peppers","onion","olive oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 103),
  ('d-stuffed-peppers-feta', 'Rice-Stuffed Peppers with Feta', 'Peppers filled with rice, chickpeas and feta, baked in tomato sauce', 'dinner', 'chickpeas', '🫑', 55, 'weekend', 722, 23, 103, 26, 14, 22, 877, '[{"name":"peppers","amount":300,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"chickpeas","amount":60,"unit":"g"},{"name":"feta","amount":60,"unit":"g"},{"name":"tomato sauce","amount":100,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Heat the oven to 200°C and boil the rice in salted water for 10 minutes, then drain","Soften the diced onion in the olive oil for 4 minutes and mix it with the rice, drained chickpeas, crumbled feta, oregano and half the tomato sauce","Halve the peppers lengthways and scoop out the seeds. Fill the pepper halves with the mixture","Stand them in a baking dish, spoon over the remaining tomato sauce, cover with foil and bake for 35 minutes"]'::jsonb, '["stovetop","oven"]'::jsonb, '["mediterranean","comfort","peppers","rice","chickpeas","feta","tomato sauce","onion","olive oil","stovetop","oven","dinner"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 104),
  ('d-pork-souvlaki-potatoes', 'Pork Souvlaki with Potatoes and Tzatziki', 'Oregano pork with roast potatoes and a cucumber garlic yogurt', 'dinner', 'pork', '🍢', 40, 'balanced', 679, 49, 65, 26, 8, 9, 133, '[{"name":"pork","amount":160,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"greek yogurt","amount":80,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"},{"name":"olive oil","amount":12,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["2 tsp dried oregano","salt","black pepper"]'::jsonb, '["Heat the oven to 210°C, cut the potatoes into wedges, toss with half the olive oil and salt and roast for 30 minutes","Cut the pork into chunks and toss with the remaining olive oil, oregano, half the juice of the lemon, salt and pepper","Grate the cucumber, squeeze out the water and mix it with the yogurt, finely grated garlic and a pinch of salt","Fry the pork over high heat for 6 to 8 minutes until browned and serve with the potatoes, tzatziki and remaining lemon"]'::jsonb, '["stovetop","oven"]'::jsonb, '["mediterranean","pork","potatoes","greek yogurt","cucumber","garlic","olive oil","lemon","stovetop","oven","dinner"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, 105),
  ('d-shrimp-tomato-feta', 'Shrimp with Tomato and Feta', 'Shrimp simmered in a garlic tomato sauce with feta, served with rice', 'dinner', 'shrimp', '🍤', 25, 'balanced', 693, 49, 74, 23, 7, 9, 1066, '[{"name":"shrimp","amount":170,"unit":"g"},{"name":"chopped tomatoes","amount":250,"unit":"g"},{"name":"feta","amount":50,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"rice","amount":70,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","black pepper","handful of fresh parsley"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Soften the diced onion in the olive oil for 4 minutes, add the sliced garlic and oregano, then the chopped tomatoes, and simmer for 8 minutes","Add the shrimp and cook for 3 minutes until pink","Crumble in the feta, let it soften for 1 minute and serve with the rice, pepper and parsley"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","shrimp","chopped tomatoes","feta","onion","garlic","olive oil","rice","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 106),
  ('d-turkey-kofta-rice', 'Turkey Kofta with Rice and Yogurt', 'Herbed turkey kofta with rice, cucumber, tomato and yogurt', 'dinner', 'turkey mince', '🦃', 25, 'balanced', 638, 41, 66, 24, 2, 7, 139, '[{"name":"turkey mince","amount":160,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"yogurt","amount":80,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Mix the turkey mince with the cumin, oregano, salt and pepper and shape into {4} small patties","Fry them in the olive oil over medium heat for 4 to 5 minutes per side until cooked through","Serve with the rice, diced cucumber and tomato and the yogurt"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","light","turkey mince","rice","yogurt","cucumber","tomato","olive oil","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 107),
  ('d-mujadara', 'Mujadara', 'Lentils and rice with deeply caramelised onions and a tomato cucumber salad', 'dinner', 'lentils', '🧅', 45, 'weekend', 684, 24, 112, 17, 12, 11, 19, '[{"name":"lentils","amount":70,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"onion","amount":150,"unit":"g"},{"name":"olive oil","amount":15,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","{450} ml water","salt","black pepper"]'::jsonb, '["Slice the onion thinly and fry it in the olive oil over medium heat for 20 minutes, stirring often, until deep brown, then lift half onto a plate","Add the rinsed lentils, cumin and water to the pan and simmer for 10 minutes","Add the rice and salt, cover and cook on low heat for 15 minutes until the water is absorbed","Serve topped with the reserved onion, with the diced cucumber and tomato on the side"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","comfort","lentils","rice","onion","olive oil","cucumber","tomato","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 108),
  ('d-ratatouille-baked-eggs', 'Ratatouille with Baked Eggs', 'Zucchini, peppers and tomato stew with eggs and potatoes', 'dinner', 'eggs', '🍆', 40, 'balanced', 550, 24, 65, 24, 14, 20, 477, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"zucchini","amount":150,"unit":"g"},{"name":"peppers","amount":120,"unit":"g"},{"name":"chopped tomatoes","amount":250,"unit":"g"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp dried thyme or oregano","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes and drain","Dice the onion, zucchini and peppers and cook them in the olive oil for 8 minutes, then add the sliced garlic and thyme","Add the chopped tomatoes and simmer for 12 minutes until thick, then season","Make {n:eggs} wells, crack in the eggs, cover and cook 5 minutes until set, and serve with the potatoes"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","light","eggs","zucchini","peppers","chopped tomatoes","potatoes","onion","garlic","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 109),
  ('d-tofu-souvlaki-bowl', 'Tofu Souvlaki Bowl', 'Lemon-oregano tofu over couscous with cucumber, tomato and peppers', 'dinner', 'tofu', '🥙', 20, 'quick', 691, 43, 75, 29, 12, 8, 43, '[{"name":"tofu","amount":180,"unit":"g"},{"name":"couscous","amount":70,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["2 tsp dried oregano","{90} ml boiling water","salt","black pepper"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Cut the tofu into cubes, toss with the oregano, salt, pepper and half the juice of the lemon and fry in the olive oil for 6 minutes until golden","Dice the cucumber, tomato and peppers","Serve the tofu over the couscous with the raw vegetables and the rest of the lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","tofu","couscous","cucumber","tomato","peppers","olive oil","lemon","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 110),
  ('d-beef-chickpea-tagine', 'Beef and Chickpea Tagine', 'Slow-cooked spiced beef with chickpeas and carrots, served with couscous', 'dinner', 'beef', '🥘', 75, 'weekend', 755, 51, 93, 19, 15, 13, 562, '[{"name":"beef","amount":150,"unit":"g"},{"name":"chickpeas","amount":80,"unit":"g"},{"name":"couscous","amount":75,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp cinnamon","1/2 tsp chili flakes","{250} ml water","salt"]'::jsonb, '["Cut the beef into chunks and brown it in the olive oil for 4 minutes, then add the diced onion for 3 minutes","Stir in the cumin, paprika, cinnamon and chili flakes, then the chopped tomatoes, sliced carrots and water","Cover and simmer on low heat for 50 to 60 minutes until the beef is tender, adding the drained chickpeas for the last 10 minutes","Pour {100} ml boiling water over the couscous with a pinch of salt, cover for 5 minutes, fluff and serve with the tagine"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","comfort","hearty","beef","chickpeas","couscous","chopped tomatoes","carrots","onion","olive oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 111),
  ('d-salmon-nicoise-salad', 'Salmon Niçoise Salad', 'Warm salmon with potatoes, green beans, egg, tomato and lettuce', 'dinner', 'salmon', '🥗', 25, 'balanced', 670, 43, 48, 35, 9, 8, 188, '[{"name":"salmon","amount":140,"unit":"g"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"green beans","amount":100,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"tomato","amount":100,"unit":"g"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp mustard","splash of red wine vinegar","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, for 15 minutes, adding the egg for the last 8 minutes and the green beans for the last 5, then drain","Fry the salmon in a little of the olive oil for 3 to 4 minutes per side","Whisk the remaining olive oil with the mustard, vinegar, salt and pepper","Arrange the lettuce, potatoes, beans, tomato wedges and quartered egg on a plate, top with the salmon and pour over the dressing"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","salmon","potatoes","green beans","eggs","tomato","lettuce","olive oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 112),
  ('d-lemon-garlic-chicken-potatoes', 'Lemon Garlic Chicken with Potatoes and Green Beans', 'Pan-roasted chicken with boiled potatoes and green beans', 'dinner', 'chicken', '🍋', 30, 'balanced', 608, 48, 69, 17, 11, 8, 104, '[{"name":"chicken","amount":170,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":12,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp dried thyme","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the green beans for the last 5, then drain","Season the chicken with the thyme, salt and pepper and fry it in the oil over medium heat for 6 minutes per side","Add the sliced garlic and the juice of the lemon to the pan for the last minute","Serve the chicken with the potatoes and beans and spoon over the pan juices"]'::jsonb, '["stovetop"]'::jsonb, '["light","chicken","potatoes","green beans","garlic","oil","lemon","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 113),
  ('d-cottage-pie', 'Cottage Pie', 'Beef mince with carrots and peas under a mashed potato top', 'dinner', 'beef mince', '🥧', 55, 'weekend', 737, 39, 74, 32, 11, 13, 304, '[{"name":"beef mince","amount":150,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"butter","amount":10,"unit":"g"},{"name":"milk","amount":40,"unit":"ml"},{"name":"tomato paste","amount":10,"unit":"g"}]'::jsonb, '["1 stock cube","{150} ml water","salt","black pepper"]'::jsonb, '["Heat the oven to 200°C and boil the potatoes, cut into chunks, for 15 minutes, then drain and mash with the butter and milk","Brown the beef mince with the diced onion and carrots in a dry pan for 8 minutes","Stir in the tomato paste, water and stock cube and simmer for 10 minutes, then add the peas","Tip into a small baking dish, spread the mash on top and bake for 20 minutes until golden"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","beef mince","potatoes","carrots","peas","onion","butter","milk","tomato paste","stovetop","oven","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 114),
  ('d-salmon-mash-peas', 'Salmon with Mash and Peas', 'Pan-fried salmon with buttery mashed potatoes and peas', 'dinner', 'salmon', '🐟', 25, 'balanced', 714, 43, 71, 30, 12, 10, 278, '[{"name":"salmon","amount":150,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"peas","amount":80,"unit":"g"},{"name":"butter","amount":10,"unit":"g"},{"name":"milk","amount":40,"unit":"ml"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the peas for the last 2, then drain","Lift out the peas and mash the potatoes with the butter and milk","Season the salmon and fry it in a non-stick pan over medium heat for 3 to 4 minutes per side","Serve with the mash, peas and the lemon cut into wedges"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","salmon","potatoes","peas","butter","milk","lemon","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal","kosher"]'::jsonb, 115),
  ('d-chicken-spinach-curry', 'Chicken and Spinach Curry', 'Tomato-based chicken curry with spinach and yogurt, served with rice', 'dinner', 'chicken', '🍛', 35, 'balanced', 664, 49, 82, 16, 8, 11, 416, '[{"name":"chicken","amount":160,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"spinach","amount":100,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"yogurt","amount":60,"unit":"g"},{"name":"rice","amount":75,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","1/2 tsp chili flakes","1 tsp grated ginger","salt"]'::jsonb, '["Dice the onion and soften it in the oil for 5 minutes, then add the chopped garlic, ginger, curry powder and chili flakes for 1 minute","Add the chicken in chunks and cook for 3 minutes, then the chopped tomatoes, and simmer for 15 minutes","Meanwhile boil the rice in salted water for 10 to 12 minutes and drain","Stir the spinach into the curry until wilted, take it off the heat, stir in the yogurt and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["spicy","comfort","chicken","chopped tomatoes","spinach","onion","garlic","yogurt","rice","oil","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 116),
  ('d-pork-mustard-cream-mash', 'Pork in Mustard Cream Sauce with Mash', 'Pork medallions in a creamy mustard sauce with mash and green beans', 'dinner', 'pork', '🥔', 30, 'balanced', 644, 44, 62, 25, 9, 8, 183, '[{"name":"pork","amount":160,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"cream sauce","amount":60,"unit":"g"},{"name":"green beans","amount":100,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["2 tsp mustard","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the green beans for the last 5, then drain","Lift out the beans and mash the potatoes with the butter","Slice the pork into medallions, season and fry in a non-stick pan for 3 minutes per side","Stir the cream sauce and mustard into the pan, simmer for 2 minutes and serve over the pork with the mash and beans"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","light","pork","potatoes","cream sauce","green beans","butter","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, 117),
  ('d-slow-cooker-beef-stew', 'Slow Cooker Beef Stew', 'Tender beef with potatoes, carrots and peas in a rich gravy', 'dinner', 'beef', '🍲', 240, 'weekend', 638, 48, 76, 16, 12, 14, 245, '[{"name":"beef","amount":170,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"carrots","amount":100,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"tomato paste","amount":15,"unit":"g"},{"name":"flour","amount":10,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 stock cube","{300} ml water","1 tsp dried thyme","salt","black pepper"]'::jsonb, '["Cut the beef into chunks, toss it in the flour and brown it in the oil in a pan for 4 minutes","Put it in the slow cooker with the potatoes and carrots in chunks, the diced onion, tomato paste, water, stock cube and thyme","Cook on high for 4 hours or on low for 7 to 8 hours until the beef falls apart","Stir in the peas for the last 10 minutes and season"]'::jsonb, '["stovetop","slow cooker"]'::jsonb, '["comfort","light","beef","potatoes","carrots","onion","peas","tomato paste","flour","oil","stovetop","slow cooker","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 118),
  ('d-oven-fish-and-chips', 'Oven Fish and Chips', 'Crisp-coated white fish with oven chips and peas', 'dinner', 'white fish', '🍟', 40, 'balanced', 762, 52, 90, 22, 13, 9, 284, '[{"name":"white fish","amount":180,"unit":"g"},{"name":"potatoes","amount":350,"unit":"g"},{"name":"peas","amount":80,"unit":"g"},{"name":"flour","amount":15,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"oil","amount":15,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","1/2 tsp paprika"]'::jsonb, '["Heat the oven to 220°C, cut the potatoes into chips, toss with two thirds of the oil and salt and roast for 30 minutes, turning once","Season the fish and coat it in the flour mixed with the paprika, then the beaten egg, then the flour again","Fry it in the remaining oil over medium-high heat for 3 minutes per side until golden","Boil the peas for 2 minutes and serve everything with the lemon cut into wedges"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","hearty","white fish","potatoes","peas","flour","eggs","oil","lemon","stovetop","oven","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 119),
  ('d-turkey-sweet-potato-mash', 'Turkey Steaks with Sweet Potato Mash', 'Pan-fried turkey with sweet potato mash and broccoli', 'dinner', 'turkey', '🦃', 25, 'balanced', 604, 49, 70, 16, 13, 15, 392, '[{"name":"turkey","amount":170,"unit":"g"},{"name":"sweet potato","amount":300,"unit":"g"},{"name":"broccoli","amount":150,"unit":"g"},{"name":"butter","amount":8,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","salt","black pepper"]'::jsonb, '["Peel the sweet potato, cut it into chunks and boil for 12 minutes, adding the broccoli florets for the last 4, then drain","Lift out the broccoli and mash the sweet potato with the butter and a pinch of salt","Season the turkey with the paprika, salt and pepper and fry in the oil over medium heat for 4 to 5 minutes per side","Serve the turkey with the mash and broccoli"]'::jsonb, '["stovetop"]'::jsonb, '["light","turkey","sweet potato","broccoli","butter","oil","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 120),
  ('d-chicken-meatballs-mushroom-sauce', 'Chicken Meatballs in Mushroom Sauce', 'Chicken mince meatballs in a creamy mushroom sauce with rice', 'dinner', 'chicken mince', '🍄', 30, 'balanced', 703, 38, 66, 32, 3, 6, 157, '[{"name":"chicken mince","amount":160,"unit":"g"},{"name":"mushrooms","amount":100,"unit":"g"},{"name":"cream sauce","amount":70,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper","pinch of dried thyme"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Season the chicken mince, roll it into {8} small balls and brown them in the oil for 6 minutes","Add the diced onion and sliced mushrooms with the thyme and cook for 5 minutes","Pour in the cream sauce with a splash of water, simmer for 4 minutes and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","chicken mince","mushrooms","cream sauce","rice","onion","oil","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 121),
  ('d-meatballs-tomato-mash', 'Meatballs in Tomato Sauce with Mash', 'Mixed mince meatballs braised in tomato sauce, with mashed potatoes', 'dinner', 'mixed mince', '🍅', 35, 'balanced', 735, 36, 71, 35, 10, 13, 219, '[{"name":"mixed mince","amount":150,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"tomato sauce","amount":150,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"butter","amount":8,"unit":"g"},{"name":"milk","amount":30,"unit":"ml"}]'::jsonb, '["1 tsp paprika","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, drain and mash with the butter and milk","Mix the mixed mince with the finely diced onion, paprika, salt and pepper and roll into {8} balls","Brown them in a dry non-stick pan for 6 minutes, turning","Add the tomato sauce, cover and simmer for 10 minutes, then serve with the mash"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","mixed mince","potatoes","tomato sauce","onion","butter","milk","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, 122),
  ('d-pork-mince-potato-skillet', 'Pork and Potato Skillet', 'Pork mince fried with potatoes, peppers and onion', 'dinner', 'pork mince', '🥔', 30, 'balanced', 689, 31, 63, 35, 9, 9, 102, '[{"name":"pork mince","amount":140,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"peppers","amount":100,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp paprika","salt","black pepper","handful of fresh parsley"]'::jsonb, '["Cut the potatoes into 1 cm cubes and fry them in the oil over medium heat for 12 minutes until golden","Push them aside and brown the pork mince for 6 minutes","Add the diced peppers and onion with the paprika and cook for 5 minutes","Season and scatter with parsley"]'::jsonb, '["stovetop"]'::jsonb, '["pork mince","potatoes","peppers","onion","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy"]'::jsonb, 123),
  ('d-lentil-shepherds-pie', 'Lentil Shepherd''s Pie', 'Lentils, carrots and peas in gravy under olive oil mash', 'dinner', 'lentils', '🥧', 60, 'weekend', 722, 30, 125, 14, 21, 14, 143, '[{"name":"lentils","amount":80,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"carrots","amount":80,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"tomato paste","amount":15,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1 stock cube","{350} ml water","1 tsp dried thyme","salt","black pepper"]'::jsonb, '["Soften the diced onion and carrots in a third of the olive oil for 5 minutes, then add the rinsed lentils, tomato paste, thyme, water and stock cube","Simmer for 25 minutes until the lentils are tender and the sauce is thick, then stir in the peas","Meanwhile boil the potatoes, cut into chunks, for 15 minutes, drain and mash with the remaining olive oil and salt","Heat the oven to 200°C, tip the lentils into a baking dish, cover with the mash and bake for 20 minutes"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","lentils","potatoes","carrots","peas","onion","tomato paste","olive oil","stovetop","oven","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 124),
  ('d-chickpea-sweet-potato-curry', 'Chickpea and Sweet Potato Curry', 'Mild coconut curry with chickpeas, sweet potato and spinach, with rice', 'dinner', 'chickpeas', '🍠', 35, 'balanced', 815, 22, 126, 27, 19, 17, 558, '[{"name":"chickpeas","amount":150,"unit":"g"},{"name":"sweet potato","amount":200,"unit":"g"},{"name":"coconut milk","amount":80,"unit":"g"},{"name":"spinach","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"rice","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","1/2 tsp chili flakes","{200} ml water","salt"]'::jsonb, '["Dice the onion and soften it in the oil for 4 minutes, then add the chopped garlic, curry powder and chili flakes","Add the sweet potato in 2 cm cubes, the coconut milk and the water and simmer for 15 minutes until tender","Meanwhile boil the rice in salted water for 10 to 12 minutes and drain","Add the drained chickpeas and spinach to the curry, cook 3 more minutes, season and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["spicy","comfort","chickpeas","sweet potato","coconut milk","spinach","onion","garlic","rice","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 125),
  ('d-potato-pepper-egg-hash', 'Potato, Pepper and Egg Hash', 'Crisp potatoes with peppers and onion, topped with three fried eggs', 'dinner', 'eggs', '🍳', 25, 'balanced', 619, 28, 64, 28, 9, 9, 258, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"peppers","amount":100,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp paprika","salt","black pepper"]'::jsonb, '["Cut the potatoes into 1 cm cubes and fry them in two thirds of the oil over medium heat for 12 minutes until golden","Add the diced peppers and onion with the paprika and cook for 5 minutes","Fry the eggs in the remaining oil in a second pan for 2 to 3 minutes","Season the hash and serve it with the eggs on top"]'::jsonb, '["stovetop"]'::jsonb, '["light","eggs","potatoes","peppers","onion","oil","stovetop","dinner"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 126),
  ('d-garlic-butter-shrimp-rice', 'Garlic Butter Shrimp with Rice', 'Shrimp in garlic butter with rice and peas', 'dinner', 'shrimp', '🍤', 20, 'quick', 628, 48, 84, 12, 7, 6, 385, '[{"name":"shrimp","amount":180,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"peas","amount":80,"unit":"g"},{"name":"butter","amount":12,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","handful of fresh parsley"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, adding the peas for the last 2, then drain","Melt the butter in a pan and gently cook the sliced garlic for 1 minute","Add the shrimp and cook for 2 to 3 minutes until pink","Squeeze in the juice of the lemon, season and serve over the rice and peas with parsley"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","shrimp","rice","peas","butter","garlic","lemon","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 127),
  ('d-tuna-fishcakes-salad', 'Tuna Fishcakes with Salad', 'Crisp tuna and potato cakes with lettuce and tomato', 'dinner', 'tuna', '🐟', 35, 'balanced', 593, 43, 66, 20, 9, 6, 448, '[{"name":"tuna","amount":140,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"flour","amount":15,"unit":"g"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"oil","amount":12,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","handful of fresh parsley"]'::jsonb, '["Boil the potatoes, cut into chunks, for 15 minutes, drain well and mash","Mix the mash with the drained tuna, the egg, parsley, salt and pepper and shape into {4} cakes, then dust them with the flour","Fry in the oil over medium heat for 4 minutes per side until crisp and golden","Serve with the lettuce, sliced tomato and the lemon cut into wedges"]'::jsonb, '["stovetop"]'::jsonb, '["light","tuna","potatoes","eggs","flour","lettuce","tomato","oil","lemon","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 128),
  ('d-salmon-sweet-potato-traybake', 'Salmon, Sweet Potato and Broccoli Traybake', 'One-tray roast of salmon, sweet potato and broccoli with lemon', 'dinner', 'salmon', '🐟', 35, 'balanced', 684, 39, 66, 31, 13, 15, 277, '[{"name":"salmon","amount":150,"unit":"g"},{"name":"sweet potato","amount":250,"unit":"g"},{"name":"broccoli","amount":150,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1/2 tsp paprika","salt","black pepper"]'::jsonb, '["Heat the oven to 210°C","Cut the sweet potato into 2 cm cubes, toss on a tray with half the olive oil, the paprika and salt and roast for 15 minutes","Add the broccoli florets tossed in the remaining olive oil and the salmon, seasoned, and roast for 12 more minutes","Squeeze over the juice of the lemon"]'::jsonb, '["oven"]'::jsonb, '["salmon","sweet potato","broccoli","olive oil","lemon","oven","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 129),
  ('d-steak-garlic-potatoes', 'Steak with Garlic Potatoes and Green Beans', 'Seared beef steak with garlic butter potatoes and green beans', 'dinner', 'beef', '🥩', 30, 'balanced', 632, 49, 64, 21, 10, 6, 192, '[{"name":"beef","amount":180,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"butter","amount":10,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the green beans for the last 5, then drain","Toss the potatoes in the butter with the chopped garlic over low heat for 2 minutes","Season the beef generously and sear it in the oil over very high heat for 2 to 3 minutes per side","Rest the steak for 3 minutes and serve with the potatoes and beans"]'::jsonb, '["stovetop"]'::jsonb, '["light","beef","potatoes","green beans","butter","garlic","oil","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 130),
  ('d-creamy-chicken-broccoli-rice-bake', 'Creamy Chicken and Broccoli Rice Bake', 'Chicken, broccoli and rice baked in a cream sauce under cheese', 'dinner', 'chicken', '🧀', 40, 'balanced', 732, 51, 74, 25, 5, 7, 367, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"rice","amount":75,"unit":"g"},{"name":"broccoli","amount":120,"unit":"g"},{"name":"cream sauce","amount":70,"unit":"g"},{"name":"cheese","amount":25,"unit":"g"},{"name":"onion","amount":30,"unit":"g"}]'::jsonb, '["salt","black pepper","pinch of nutmeg"]'::jsonb, '["Heat the oven to 200°C and boil the rice in salted water for 8 minutes, adding the broccoli florets for the last 2, then drain","Cut the chicken into small pieces and fry it with the diced onion in a non-stick pan for 5 minutes","Mix everything with the cream sauce, nutmeg, salt and pepper in a small baking dish","Scatter over the grated cheese and bake for 15 minutes until golden"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","chicken","rice","broccoli","cream sauce","cheese","onion","stovetop","oven","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 131),
  ('d-crispy-tofu-sweet-potato', 'Crispy Tofu with Sweet Potato and Green Beans', 'Pan-crisped tofu with roasted sweet potato and green beans', 'dinner', 'tofu', '🍠', 35, 'balanced', 617, 37, 64, 28, 15, 14, 170, '[{"name":"tofu","amount":180,"unit":"g"},{"name":"sweet potato","amount":250,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp smoked paprika","salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Heat the oven to 210°C, cut the sweet potato into wedges, toss with half the oil, the paprika and salt and roast for 25 minutes","Add the green beans to the tray for the last 10 minutes","Pat the tofu dry, cut into slabs, season and fry in the remaining oil for 4 minutes per side until crisp","Serve together with a squeeze of lemon"]'::jsonb, '["stovetop","oven"]'::jsonb, '["light","tofu","sweet potato","green beans","oil","stovetop","oven","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 132),
  ('d-smoky-bean-potato-stew', 'Smoky Bean and Potato Stew', 'Kidney beans, potatoes and carrots in a smoky tomato broth', 'dinner', 'kidney beans', '🥘', 35, 'balanced', 589, 22, 102, 13, 22, 20, 718, '[{"name":"kidney beans","amount":180,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"carrots","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp smoked paprika","1 stock cube","{250} ml water","salt","black pepper"]'::jsonb, '["Dice the onion and soften it in the olive oil for 4 minutes, then stir in the paprika","Add the potatoes and carrots in chunks, the chopped tomatoes, water and stock cube and simmer for 20 minutes until tender","Stir in the drained kidney beans and cook 5 more minutes","Season with salt and pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","light","kidney beans","potatoes","carrots","chopped tomatoes","onion","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 133),
  ('d-turkey-burgers-sweet-potato-wedges', 'Turkey Burgers with Sweet Potato Wedges', 'Lean turkey burger with lettuce and tomato and roasted sweet potato', 'dinner', 'turkey mince', '🍔', 35, 'balanced', 733, 45, 83, 25, 13, 15, 554, '[{"name":"turkey mince","amount":160,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"sweet potato","amount":250,"unit":"g"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","salt","black pepper","1 tsp mustard"]'::jsonb, '["Heat the oven to 220°C, cut the sweet potato into wedges, toss with most of the oil, the paprika and salt and roast for 25 minutes","Season the turkey mince, shape it into a patty and fry in the remaining oil for 5 minutes per side until cooked through","Toast the bread and spread with mustard","Add the lettuce, burger and sliced tomato and serve with the wedges"]'::jsonb, '["stovetop","oven"]'::jsonb, '["turkey mince","bread","sweet potato","lettuce","tomato","oil","stovetop","oven","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 134),
  ('d-fish-pie', 'Fish Pie', 'White fish and peas in a cream sauce under cheesy mash', 'dinner', 'white fish', '🥧', 45, 'weekend', 682, 47, 64, 27, 9, 8, 440, '[{"name":"white fish","amount":170,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"peas","amount":60,"unit":"g"},{"name":"cream sauce","amount":70,"unit":"g"},{"name":"butter","amount":8,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"}]'::jsonb, '["salt","black pepper","pinch of nutmeg"]'::jsonb, '["Heat the oven to 200°C and boil the potatoes, cut into chunks, for 15 minutes, then drain and mash with the butter","Cut the fish into chunks and mix it in a small baking dish with the peas, cream sauce, nutmeg, salt and pepper","Spread the mash over the top and scatter with the grated cheese","Bake for 25 minutes until golden and bubbling at the edges"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","white fish","potatoes","peas","cream sauce","butter","cheese","stovetop","oven","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal","kosher"]'::jsonb, 135),
  ('d-honey-mustard-pork-rice', 'Honey Mustard Pork with Rice and Broccoli', 'Pork strips in a honey mustard glaze with rice and broccoli', 'dinner', 'pork', '🍯', 25, 'balanced', 655, 44, 78, 18, 5, 11, 137, '[{"name":"pork","amount":160,"unit":"g"},{"name":"rice","amount":75,"unit":"g"},{"name":"broccoli","amount":150,"unit":"g"},{"name":"honey","amount":10,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["2 tsp mustard","salt","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, adding the broccoli florets for the last 3, then drain","Cut the pork into strips, season and fry in the oil over high heat for 5 minutes until browned","Stir in the honey and mustard with a splash of water and bubble for 1 minute","Serve the pork and its glaze over the rice and broccoli"]'::jsonb, '["stovetop"]'::jsonb, '["pork","rice","broccoli","honey","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy"]'::jsonb, 136),
  ('d-chicken-caesar-salad', 'Chicken Caesar-Style Salad', 'Chicken over crisp lettuce with croutons, parmesan and a lemon yogurt dressing', 'dinner', 'chicken', '🥗', 20, 'quick', 612, 58, 42, 24, 8, 8, 662, '[{"name":"chicken","amount":170,"unit":"g"},{"name":"lettuce","amount":100,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"parmesan","amount":20,"unit":"g"},{"name":"yogurt","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp mustard","1 small grated garlic clove if you like","salt","black pepper"]'::jsonb, '["Cut the bread into cubes and fry them in half the olive oil for 3 minutes until crisp, then set aside","Season the chicken and fry it in the remaining olive oil for 5 to 6 minutes per side, then slice","Mix the yogurt with the mustard, the juice of the lemon, half the grated parmesan, salt and pepper","Toss the torn lettuce in the dressing and top with the chicken, croutons and remaining parmesan"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","chicken","lettuce","bread","parmesan","yogurt","olive oil","lemon","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 137),
  ('d-thai-beef-noodle-salad', 'Thai Beef Noodle Salad', 'Seared beef with cold noodles, cucumber, carrot and a chili-lime dressing', 'dinner', 'beef', '🥗', 20, 'quick', 526, 44, 54, 14, 5, 6, 803, '[{"name":"beef","amount":150,"unit":"g"},{"name":"noodles","amount":60,"unit":"g"},{"name":"cucumber","amount":100,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"soy sauce","amount":12,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["juice of half a lime","1/2 tsp chili flakes","handful of fresh mint or coriander"]'::jsonb, '["Cook the noodles according to the packet, drain and rinse under cold water","Sear the beef in the oil over very high heat for 2 minutes per side, rest it for 3 minutes and slice thinly","Mix the soy sauce with the lime juice and chili flakes","Toss the noodles with the cucumber and carrots cut into thin strips, the shredded lettuce and the dressing, and top with the beef and herbs"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","fresh","quick","light","beef","noodles","cucumber","carrots","lettuce","soy sauce","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 138),
  ('d-chickpea-avocado-quinoa-salad', 'Chickpea, Avocado and Quinoa Salad', 'Big salad of quinoa, chickpeas, avocado, tomato and cucumber', 'dinner', 'chickpeas', '🥑', 20, 'quick', 745, 24, 97, 34, 26, 12, 390, '[{"name":"chickpeas","amount":150,"unit":"g"},{"name":"quinoa","amount":60,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","handful of fresh parsley"]'::jsonb, '["Rinse the quinoa and simmer it in salted water for 12 to 15 minutes, then drain and cool slightly","Dice the avocado, tomato and cucumber","Toss the quinoa with the drained chickpeas, the vegetables, olive oil, the juice of the lemon, salt, pepper and parsley"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","chickpeas","quinoa","avocado","tomato","cucumber","olive oil","lemon","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 139),
  ('d-chicken-alfredo', 'Chicken Alfredo', 'Pasta in a parmesan cream sauce with chicken and broccoli', 'dinner', 'chicken', '🍝', 25, 'balanced', 967, 68, 93, 35, 6, 8, 460, '[{"name":"chicken","amount":180,"unit":"g"},{"name":"pasta","amount":110,"unit":"g"},{"name":"cream sauce","amount":100,"unit":"g"},{"name":"parmesan","amount":20,"unit":"g"},{"name":"broccoli","amount":100,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper","pinch of nutmeg"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet, adding the broccoli florets for the last 3 minutes, then drain and keep a little of the water","Slice the chicken, season and fry it in the butter over medium-high heat for 6 minutes","Add the cream sauce, nutmeg and a splash of pasta water and simmer for 2 minutes","Toss in the pasta, broccoli and grated parmesan and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","hearty","chicken","pasta","cream sauce","parmesan","broccoli","butter","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 140),
  ('d-beef-stroganoff', 'Beef Stroganoff', 'Beef strips and mushrooms in a creamy sauce over rice', 'dinner', 'beef', '🍄', 30, 'balanced', 905, 55, 94, 34, 4, 9, 245, '[{"name":"beef","amount":180,"unit":"g"},{"name":"mushrooms","amount":150,"unit":"g"},{"name":"cream sauce","amount":90,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"rice","amount":100,"unit":"g"},{"name":"butter","amount":10,"unit":"g"}]'::jsonb, '["1 tsp mustard","1 tsp paprika","salt","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the beef into thin strips, season and sear it in half the butter over very high heat for 2 minutes, then set aside","Cook the sliced onion and mushrooms in the remaining butter for 6 minutes, then stir in the paprika and mustard","Add the cream sauce, simmer for 2 minutes, return the beef to warm through and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","beef","mushrooms","cream sauce","onion","rice","butter","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 141),
  ('d-creamy-salmon-spinach-pasta', 'Creamy Salmon and Spinach Pasta', 'Pasta with flaked salmon and spinach in a garlic cream sauce', 'dinner', 'salmon', '🐟', 20, 'quick', 895, 51, 84, 39, 6, 6, 238, '[{"name":"salmon","amount":160,"unit":"g"},{"name":"pasta","amount":100,"unit":"g"},{"name":"cream sauce","amount":80,"unit":"g"},{"name":"spinach","amount":100,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a little of the water","Fry the salmon in a non-stick pan over medium heat for 3 to 4 minutes per side, then break it into flakes","Add the sliced garlic for 30 seconds, then the cream sauce, spinach and a splash of pasta water","Toss in the pasta and finish with pepper and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","quick","hearty","salmon","pasta","cream sauce","spinach","garlic","stovetop","dinner"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, 142),
  ('d-peanut-tofu-stir-fry', 'Peanut Tofu Stir-Fry', 'Crisp tofu with broccoli and peppers in a peanut soy sauce over rice', 'dinner', 'tofu', '🥜', 25, 'balanced', 948, 57, 99, 42, 13, 9, 1293, '[{"name":"tofu","amount":220,"unit":"g"},{"name":"rice","amount":90,"unit":"g"},{"name":"peanut butter","amount":25,"unit":"g"},{"name":"broccoli","amount":150,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"soy sauce","amount":20,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["4 tbsp hot water","1 tsp grated ginger","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Cut the tofu into cubes and fry in the oil over medium-high heat for 6 minutes until golden","Add the broccoli florets, sliced peppers and ginger with a splash of water and stir-fry for 4 minutes","Whisk the peanut butter with the soy sauce, hot water and lime juice, pour it in, toss for 1 minute and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","hearty","tofu","rice","peanut butter","broccoli","peppers","soy sauce","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","halal","kosher"]'::jsonb, 143),
  ('d-lentil-chickpea-curry', 'Lentil and Chickpea Curry', 'Thick coconut curry of lentils, chickpeas and spinach with rice', 'dinner', 'lentils', '🍛', 40, 'balanced', 908, 37, 135, 27, 20, 9, 379, '[{"name":"lentils","amount":80,"unit":"g"},{"name":"chickpeas","amount":120,"unit":"g"},{"name":"coconut milk","amount":80,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"spinach","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","1/2 tsp chili flakes","{350} ml water","salt"]'::jsonb, '["Dice the onion and soften it in the oil for 4 minutes, then stir in the curry powder and chili flakes","Add the rinsed lentils and the water and simmer for 20 minutes until the lentils are soft","Meanwhile boil the rice in salted water for 10 to 12 minutes and drain","Stir the drained chickpeas, coconut milk and spinach into the lentils, cook 5 more minutes, season with salt and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["spicy","comfort","hearty","lentils","chickpeas","coconut milk","rice","spinach","onion","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 144),
  ('d-loaded-bean-rice-burritos', 'Loaded Bean and Rice Burritos', 'Two burritos packed with spiced kidney beans, rice and corn', 'dinner', 'kidney beans', '🌯', 25, 'balanced', 912, 31, 157, 18, 17, 14, 1451, '[{"name":"kidney beans","amount":200,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"rice","amount":60,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp smoked paprika","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Warm the drained kidney beans in the oil with the cumin, paprika and salt for 3 minutes, crushing about half of them","Stir in the rice, corn and lime juice","Warm the tortillas, divide the filling between them, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","hearty","kidney beans","tortilla","rice","corn","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 145),
  ('d-spaghetti-carbonara', 'Spaghetti Carbonara', 'Spaghetti with crisp bacon in a silky egg and parmesan sauce', 'dinner', 'eggs', '🥓', 20, 'quick', 899, 45, 84, 41, 4, 4, 907, '[{"name":"bacon","amount":60,"unit":"g"},{"name":"pasta","amount":110,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"parmesan","amount":25,"unit":"g"}]'::jsonb, '["plenty of black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a cup of the water","Fry the chopped bacon in a dry pan for 5 minutes until crisp, then take the pan off the heat","Beat the eggs with the grated parmesan and pepper","Toss the hot pasta in the pan with the bacon, then stir in the egg mixture and a splash of pasta water off the heat until creamy"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","quick","hearty","bacon","pasta","eggs","parmesan","stovetop","dinner"]'::jsonb, '["nut-allergy"]'::jsonb, 146),
  ('d-butter-chicken', 'Butter Chicken with Rice', 'Chicken in a mildly spicy, creamy tomato sauce with rice', 'dinner', 'chicken', '🍛', 35, 'balanced', 898, 54, 104, 29, 5, 12, 253, '[{"name":"chicken","amount":180,"unit":"g"},{"name":"tomato sauce","amount":150,"unit":"g"},{"name":"cream sauce","amount":80,"unit":"g"},{"name":"butter","amount":10,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"rice","amount":100,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"}]'::jsonb, '["1 tbsp curry powder","1/2 tsp chili flakes","1 tsp grated ginger","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Soften the diced onion in the butter for 4 minutes, then add the chopped garlic, ginger, curry powder and chili flakes for 1 minute","Add the chicken in chunks and cook for 4 minutes, then the tomato sauce, and simmer for 12 minutes","Stir in the cream sauce, simmer 2 more minutes, season with salt and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["spicy","comfort","hearty","chicken","tomato sauce","cream sauce","butter","onion","rice","garlic","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 147),
